    arr = list(map(int,input().split()))
    nums = {}
    for i in range(1,n+1):
        nums[i] = []

    dp = [0]*n
    heap = []
    for i in range(n):
        nums[arr[i]].append(i)
        if arr[i] == 1:
            dp[i] = 1
            heapq.heappush(heap,(arr[i],i))

    if not heap:
        print(-1)
        return
    visited = set()
    while heap:
        curr = heapq.heappop(heap)
        if curr not in visited:
            visited.add(curr)
            index = curr[1]
            num = curr[0]
            #print(curr,num)
            if num+1 in nums.keys():
                for kid in nums[num+1]:
                    if kid > index:
                        #print(num,kid,dp[kid])
                        dp[kid] = max(dp[kid],dp[index]+1)
                        heapq.heappush(heap,(num+1,kid))

    #print(dp)
    print(n-max(dp))



