def solve(arg: str) -> str:
    h, w, a, b = map(int, arg.split())
    mat = [[0] * w for _ in range(h)]
    sumy = [0] * w

    for y in range(h):
        sumx = 0
        for x in range(w):
            if(
                (sumy[x] < b and sumx < a) or
                (sumy[x] < h - b and sumx < a) or
                (sumy[x] < b and sumx < w - a) or
                (sumy[x] < h - b and sumx < w - a)
            ):
                mat[y][x] = 1
                sumx += 1
                sumy[x] += 1
        if(min(sumx, w - sumx) != a):
            return 'No'

    for s in sumy:
        if(min(s, h - s) != b):
            return 'No'

    ret = ''
    for y in range(h):
        for x in range(w):
            ret += str(mat[y][x])
        if(y != h-1):
            ret += '\n'

    return ret


