import java.util.*;

public class Main {
  public static long MOD = (long)Math.pow(10, 9) + 7;
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    long n = sc.nextLong();
    long a = sc.nextLong();
    long b = sc.nextLong();
    long c = sc.nextLong();

    long[] kai = new long[(int)(2 * n)];
    kai[0] = 1;
    for(int i = 1; i < (int)(2 * n); i++) {
      kai[i] = (i * kai[i - 1]) % MOD;
    }
    // comb[i] = (n + i - 1, n - 1)
    long[] comb = new long[(int)n];
    for(int i = 0; i < (int)n; i++) {
      long t1 = func(kai[(int)n - 1], MOD - 2);
      long t2 = func(kai[i], MOD - 2);
      long t3 = (kai[(int)n + i - 1] * t1) % MOD;
      t3 = (t3 * t2) % MOD;
      comb[i] = t3;
    }
    long inv = func(a + b, MOD - 2);
    long pa = (a * inv) % MOD;
    long pb = (b * inv) % MOD;
    long ans = 0;
    for(int i = 0; i < (int)n; i++) {
      long q1 = func(pa, n);
      long q2 = func(pb, i);
      long r1 = func(pa, i);
      long r2 = func(pb, n);
      long p1 = (q1 * q2) % MOD;
      long p2 = (r1 * r2) % MOD;
      long p3 = (p1 + p2) % MOD;
      long t = (comb[i] * p3) % MOD;
      t = (t * (n + i)) % MOD;
      ans = (ans + t) % MOD;
    }
    long s = func(100 - c, MOD - 2);
    ans = (ans * 100) % MOD;
    ans = (ans * s) % MOD;
    System.out.println(ans);
  }

  public static long func(long a, long x) {
    if(x == 0) {
      return 1;
    } else {
      if(x % 2 == 0) {
        long t = func(a, x / 2);
        return (t * t) % MOD;
      } else {
        return (a * func(a, x - 1)) % MOD;
      }
    }
  }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = Integer.parseInt(sc.next());
        int w = Integer.parseInt(sc.next());
        byte a[][] = new byte[h][w];
        for(int i = 0; i < h; i++){
        	String s = sc.next();
        	byte sb[] = s.getBytes();
        	for (int j = 0; j < w; j++){
        		a[i][j] = sb[j];
        	}
        }

        int depth[][] = new int[h][w];
        Deque<Integer> q = new ArrayDeque<Integer>();
        for(int i = 0; i < h; i++){
        	for(int j = 0; j < w; j++){
                if (a[i][j] == (byte)('#') ){
                	depth[i][j] = 0;
                	q.addLast(i * 1000 + j);
                }
        	}
        }
        while(! q.isEmpty()){
        	Integer r = q.removeFirst();
        	int i = r / 1000;
        	int j = r % 1000;
        	if (i > 0 && a[i-1][j] == (byte)('.') && depth[i-1][j] == 0){
        		depth[i-1][j] = depth[i][j] + 1;
        		q.addLast(i * 1000 - 1000 + j);
        	}
        	if (i < h-1 && a[i+1][j] == (byte)('.') && depth[i+1][j] == 0){
        		depth[i+1][j] = depth[i][j] + 1;
        		q.addLast(i * 1000 + 1000 + j);
        	}
        	if (j > 0 && a[i][j-1] == (byte)('.') && depth[i][j-1] == 0){
        		depth[i][j-1] = depth[i][j] + 1;
        		q.addLast(i * 1000 + j - 1);
        	}
        	if (j < w-1 && a[i][j+1] == (byte)('.') && depth[i][j+1] == 0){
        		depth[i][j+1] = depth[i][j] + 1;
        		q.addLast(i * 1000 + j + 1);
        	}
        }
        int ret = 0;
        for(int i = 0; i < h; i++){
        	for(int j = 0; j < w; j++){
        		if (ret < depth[i][j]) ret = depth[i][j];
        	}
    	}
        System.out.println(ret);
	}
}

