def convert_time_format(seconds:int) -> str:
    if seconds < 0:
        raise ValueError('Paramter seconds is less than 0.')
    if seconds > 86400:
        raise ValueError('Parameter seconds is larger than 86400')

    min = int(seconds / 60)
    sec = seconds % 60
    hour = int(min / 60)
    min = min % 60

    return '{0}:{1}:{2}'.format(hour, min, sec)

