			double dbBottom = list.get(0);
			double dbSide = list.get(1);
			double dbActAngle = list.get(2);
			double dbAngle = dbActAngle * Math.PI / 180;

			//面積。
			double dbSin = Math.sin(dbAngle);
			double dbArea = dbBottom * dbSide * dbSin / 2.0;
