            p[i] = sc.nextInt();
        }
        for (int i = 0; i < b; i++) {
            q[i] = sc.nextInt();
        }
        for (int i = 0; i < c; i++) {
            r[i] = sc.nextInt();
        }

        Arrays.sort(p);
        Arrays.sort(q);
        Arrays.sort(r);


        long ans = 0;
        int rid = c;
        while (true) {
            if (rid <= 0)
                break;
            boolean puse = false;
            boolean quse = false;

            long pscore = (x > 0) ? p[a - x] : 0;
            long qscore = (y > 0) ? q[b - y] : 0;

            if (x > 0 && pscore < r[rid - 1]) {
                puse = true;
            }
            if (y > 0 && qscore < r[rid - 1]) {
                quse = true;
            }


            if (puse && quse) {
                if (pscore > qscore) {
                    y--;
                    rid--;
