def solve(l,n,m,x):
	totPossible = defaultdict(int)
	for j in range(1,m+1):
		for i in range(n):
			totPossible[j] += l[i][j]
	for i in totPossible:
		if(totPossible[i] < x):
			return -1
	combs = []
	for i in range(1,n+1):
		ll = [i for i in range(n)]
		c = list(combinations(ll,i))
		combs.append(c)
	minn = maxsize
	ccc = []
	for i in combs:
		for j in i:
			ccc.append(j)

	for c in ccc:
		ll = [0]*m
		bought = [0]*n
		curr = 0
		for i in c:
			bought[i] = 1
		for i in range(n):
			if(bought[i]):
				for j in range(1,m+1):
					ll[j-1] += l[i][j]
		f = 1
		for i in range(len(ll)):
			if(ll[i] < x):
				f = 0
				break
		if(f):
			for i in range(n):
				if(bought[i]):
					curr += l[i][0]
			minn = min(minn,curr)
	return minn


