		int data_count = 0;

		out: while (true) {
			input_n = sc.nextLine();
			n = Integer.parseInt(input_n);
			if (n == 0) {
				break out;
			}
			if (n < 0 || n > 1000) {
				judge_n = false;
				break out;
			}

			input_test = sc.nextLine();
			Test_String = input_test.split(" ");

			if (Test_String.length != n) {
				judge_test = false;
				break out;

			}
			// 始:平均値を求める
			m = 0.0;
			Test_Score = new int[n];
