"""
整数N,Kが与えられます。
N以下の正の整数の組(a,b,c)であって、a+b,b+c,c+aがすべてKの倍数であるようなものの個数を求めてください。
ただし、a,b,cの順番を入れ替えただけの組も異なるものとして数えます。
また、a,b,cの中に同じものがあっても構いません。
"""


def main(str):
    num = str.split()
    N = int(num[0])
    K = int(num[1])
    if(K%2 != 0):
        cnt = 0
        for a in range(1, N+1):
            if(a%K == 0):
                cnt += 1
        cnt = cnt ** 3

    else:
        cnt1 = 0
        cnt2 = 0
        for a in range(1, N+1):
            if(a%K == 0):
                cnt1 += 1
        for a in range(1, N+1):

            if(a%K == K/2):
                cnt2 += 1

        cnt = cnt1 ** 3 + cnt2 ** 3

    print(cnt)


if __name__ == "__main__":
    main(input())

