import java.util.*;
import java.math.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int M = sc.nextInt();
    int K = sc.nextInt();
    int[] A = new int[M];
    int[] B = new int[M];
    for (int i = 0; i < M; i++) {
      A[i] = sc.nextInt();
      B[i] = sc.nextInt();
    }
    int[] C = new int[K];
    int[] D = new int[K];
    for (int i = 0; i < K; i++) {
      C[i] = sc.nextInt();
      D[i] = sc.nextInt();
    }
    sc.close();

    Map<Integer, Set<Integer>> f = new HashMap<>();
    for (int i = 0; i < M; i++) {
      Integer a = Integer.valueOf(A[i]);
      Integer b = Integer.valueOf(B[i]);
      if (!f.containsKey(a)) f.put(a, new HashSet<>());
      f.get(a).add(b);
      if (!f.containsKey(b)) f.put(b, new HashSet<>());
      f.get(b).add(a);
    }

    Map<Integer, Set<Integer>> b = new HashMap<>();
    for (int i = 0; i < K; i++) {
      Integer c = Integer.valueOf(C[i]);
      Integer d = Integer.valueOf(D[i]);
      if (!b.containsKey(c)) b.put(c, new HashSet<>());
      b.get(c).add(d);
      if (!b.containsKey(d)) b.put(d, new HashSet<>());
      b.get(d).add(c);
    }

    int[] gn = new int[N + 1];
    int[] gc = new int[N + 1];
    for (int i = 1; i < N + 1; i++) {
      if (gn[i] != 0) continue;

      Deque<Integer> q = new ArrayDeque<>();
      q.addLast(i);
      while (!q.isEmpty()) {
        Integer n = q.pollLast();
        if (gn[n] != 0) continue;
        gn[n] = i;
        gc[i]++;
        q.addAll(f.getOrDefault(n, Collections.emptySet()));
      }
    }

    int[] ans = new int[N + 1];
    for (int i = 1; i < N + 1; i++) {
      ans[i] = gc[gn[i]] - 1;

      Integer a = Integer.valueOf(i);
      Set<Integer> na = new HashSet<>();
      na.addAll(b.getOrDefault(a, Collections.emptySet()));
      na.addAll(f.getOrDefault(a, Collections.emptySet()));

      for (Integer n : na)
        if (gn[i] == gn[n]) ans[i]--;
    }

    StringBuilder buf = new StringBuilder();
    for (int i = 1; i < N + 1; i++)
      buf.append(ans[i]).append(" ");
    buf.setLength(buf.length() - 1);
    System.out.println(buf);
  }
}

