				if(nn > min){
					min = nn;
				}
				if(nums.get(nums.size()-1)*nn >= 0){
					long j = nums.get(nums.size()-1) + nn;
					nums.set(nums.size()-1, j);
				}
				else {
					nums.add((long)nn);
				}	
			}
			if(nums.size() == 1 && nums.get(0) < 0){
				max = min;
			}
			else{
				if(nums.get(0) < 0){
					nums.remove(0);
				}
				if(nums.get(nums.size()-1) < 0){
					nums.remove(nums.size()-1);
				}

				max = nums.get(0);
				for(int h = 0;h < nums.size(); h= h+2){
					long sub = 0;
