          A[i] = sc.nextInt();
        }
        if(i > 0){
          Atotal[i] = Atotal[i-1] + A[i-1];
          if(Amax == -1 && Atotal[i] > K){
            Amax = i-1;
          }
        }
      }
      if(Amax == -1){
        Amax = N;
      }

      Btotal[0] = 0;
      B[0] = sc.nextInt();
