        s.append([(f ** i, f ** (n - i)) for i in xrange(n + 1)])

    best = float('inf')
    for case in product(*s):
        a = b = 1
        for aa, bb in case:
            a *= aa
            b *= bb
        best = min(best, a + b - 2)
