        list.sort(Comparator.reverseOrder());
        long sum = list.get(0);
        int j = 1;
        boolean even = false;
        for (int i = 1; i < num - 1; i++) {
            sum += list.get(j);
            if (even) {
                j++;
            }
            even = !even;
        }

        System.out.print(sum);
    }
