        long ans = 0;
        int t_ptr = 0;
        int a_ptr = 0;
        for (int i = 0 ; i < n ; i++) {
        	if (t_turn) {
        		Dish d;
        		while (true) {
        			d = t_list.get(t_ptr);
        			t_ptr++;
        			if (d.used == false) break;
        		}
        		d.used = true;
        		ans += d.t;
        		t_turn = !t_turn;
