        graph[i][j] = 1;
      else
        graph[i][j] = 0;
    }
  }

  int a, b;
  for(int i=0; i<m; i++){
    cin >> a >> b;
    graph[a-1][b-1] = graph[b-1][a-1] = 1;
  }

  // for(int i=0; i<n; i++){                                                                                                                                                    
