  for(int i=0; i<n; i++){
    for(int j=i+1; j<n; j++){
      if(graph[i][j] == 1){
        graph[i][j] = 0;

        // copy graph                                                                                                                                                           
        for(int in=0; in<n; in++){
          for(int jn=0; jn<n; jn++){
            graph_t[in][jn] = graph[in][jn];
          }
        }

        for(int kn=0; kn<n; kn++){
          for(int in=0; in<n; in++){
            for(int jn=0; jn<n; jn++){
              if(kn != in && kn != jn && in != jn &&
