{
    int d, g;
    cin>>d>>g;
    int p[d], c[d];
    for(int i=0; i<d; i++)
        cin>>p[i]>>c[i];
    int n= g/100;
    int sol[n+1][d][d];
    int opt[n+1][d];
    int min_i= g/100;
    for(int i=0; i<d; i++)
    {
        for(int j=0; j<d; j++)
        {
            sol[0][i][j] = 0;
        }
        opt[0][i] = 0;
    }
    for(int i=0; i<=n; i++)
    {
        if(i<p[0])
        {
            opt[i][0]= 100*i;
            sol[i][0][0] = i;
        }
        else
        {
            opt[i][0]= 100*p[0] + c[0];
            sol[i][0][0] = p[0];
        }
        for(int j=1; j<d; j++)
        {
            sol[i][0][j] = 0;
        }
        if(opt[i][0]>=g && i<min_i) min_i = i;
    }

    bool finished = false;
    for(int i=1; i<=n; i++)
    {
        for(int j=1; j<d; j++)
        {
            opt[i][j] = opt[i][j-1];
            for(int k=0; k<d; k++)
            {
                sol[i][j][k] = sol[i][j-1][k];
            }
            //find max
            for(int m=1; m<=min(p[j], i); m++)
            {
                if(opt[i][j]<opt[i-m][j-1]+ m*(j+1)*100)
                {
                    opt[i][j] = opt[i-m][j-1]+ m*(j+1)*100;
                    for(int k=0; k<d; k++)
                    {
                        sol[i][j][k] = sol[i-m][j-1][k];
                    }
                    sol[i][j][j]=m;
                }
                if(m==p[j] && opt[i][j]<opt[i-m][j-1]+ m*(j+1)*100 + c[j])
                {
                    opt[i][j] = opt[i-m][j-1]+ m*(j+1)*100 + c[j];
                    for(int k=0; k<d; k++)
                    {
                        sol[i][j][k] = sol[i-m][j-1][k];
                    }
                    sol[i][j][j]=m;
                }
            }
            if(opt[i][j]>= g && i< min_i)
            {
                min_i = i;
                finished=true;
                break;
            }
        }
        if(finished) break;
    }
    cout<<min_i<<endl;

	return 0;
