    priority_queue <pair<int, int>, vector <pair <int, int> >, greater <pair <int, int> > > pq;
    for(int i = 1; i < v + 1; i++)
    {
        pq.push(make_pair(indeg[i], i));
    }
    while(!pq.empty())
    {
        int prev = pq.top().second;
        pq.pop();
        if(indeg[prev] == 0 && !vis[prev])
        {
            vis[prev] = 1;
            sorted.push_back(prev);
        }
        for(int i = 0; i < g[prev].size(); i++)
        {
            if(indeg[g[prev][i]] > 0)
            {
                indeg[g[prev][i]] -= 1;
                pq.push(make_pair(indeg[g[prev][i]], g[prev][i]));
