int main ()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    size_t n, m = 0;
    cin >> n; // 店の件数.
    cin >> m; // 必要なドリンク数.
    assert(1 <= n && n <= pow(10, 5));
    assert(1 <= m && m <= pow(10, 5));

    map<int64_t, size_t> price_and_num;
    for(size_t i = 0; i < n; ++i)
    {
        int64_t price;
        size_t num;
        cin >> price;
        cin >> num;
        assert(1 <= price && price <= pow(10, 9));
        assert(1 <= num && num <= pow(10, 5));

        if (price_and_num.find(price) != price_and_num.end()) {
            price_and_num[price] += num;
        } else {
            price_and_num[price] = num;
        }
    }

    int64_t price_sum = 0;
    size_t current_num = 0;
    for (auto itr = price_and_num.begin(); itr != price_and_num.end(); ++itr)
    {
        if ((current_num + itr->second) < m) {
            // 必要個数を超えない場合.
            price_sum += itr->first * itr->second;
            current_num += itr->second;
            //cout << current_num << " " << price_sum << endl;
        } else {
            // 必要個数を超える場合(この際のみ二重のforループ).
            for(size_t i = 0; i < itr->second; ++i)
            {
                price_sum += itr->first;
                current_num++;
                //cout << current_num << " " << price_sum << endl;
                if (current_num == m) {
                    break;
                }
                assert(current_num <= m);
            }
            break;
        }
    }

    assert(current_num == m);
    cout << price_sum << endl;
}

