int main(void)
{
    int64_t N;
    std::cin >> N;

    std::vector<int64_t> Ls(N);
    for (auto& L : Ls) {
        std::cin >> L;
    }

    int64_t count = 0;
    for (int64_t i = 0; i < N-2; ++i) {
    for (int64_t j = 1; j < N-1; ++j) {
    for (int64_t k = 2; k < N-0; ++k) {
        if (!(i < j && j < k)) continue;
        int64_t Li = Ls.at(i);
        int64_t Lj = Ls.at(j);
        int64_t Lk = Ls.at(k);
        if (Li == Lj || Lj == Lk || Li == Lk) continue;
        if (Li > Lj && Li > Lk) {
            if (std::abs(Lj - Lk) < Li && Li < (Lj+Lk)) {
                count++;
            }
        } else if (Lj > Li && Lj > Lk) {
            if (std::abs(Li - Lk) < Lj && Lj < (Li+Lk)) {
                count++;
            }
        } else if (Lk > Li && Lk > Lj) {
            if (std::abs(Li - Lj) < Lk && Lk < (Li+Lj)) {
                count++;
            }
        }
    }
    }
    }

