      c = (c * kai[(int)(n + k - t - 1)]) % MOD;
      long d = kai[(int)(n - 1)];
      long e = kai[(int)(k - t)];
      c = (c * func(d, MOD - 2)) % MOD;
      c = (c * func(e, MOD - 2)) % MOD;
      ans = (ans + c) % MOD;
    }
    System.out.println(ans);
  }

  public static long func(long a, long x) {
    if(x == 0) return 1;
    if((x % 2) == 0) {
      long t = func(a, x / 2);
      return (t * t) % MOD;
    } else {
      return (a * func(a, x - 1)) % MOD;
    }
  }
}

