  cin >> n >> m;

  auto cmp = [](auto &p1, auto &p2) {
    if (p1.first > p2.first) {
      return true;
    } else if (p1.first < p2.first) {
      return false;
    } else {
      return p1.second < p2.second;
    }
  };
  priority_queue<pair<int, ll>, vector<pair<int, ll>>, decltype(cmp)> q1(cmp);

  for (int i = 0; i < n; i++) {
    int a;
    ll b;
    cin >> a >> b;
    q1.push({a, b});
  }

  ll ans = 0;
  priority_queue<ll, vector<ll>, less<ll>> q2;
  for (int i = 1; i <= m; i++) {
    if (q1.empty() && q2.empty()) {
      continue;
    } else if (q1.empty()) {
      ans += q2.top();
      q2.pop();
    } else if (q2.empty()) {
      auto [a, b] = q1.top();
      if (a > i)
        continue;
      ans += b;
      q1.pop();
    } else {
      auto [a1, b1] = q1.top();
      auto b2 = q2.top();
      if (a1 <= i && b1 > b2) {
        ans += b1;
        q1.pop();
      } else {
        ans += b2;
        q2.pop();
      }
    }
    while (!q1.empty() && q1.top().first <= i) {
      q2.push(q1.top().second);
      q1.pop();
    }
  }
