        long B = sc.nextLong();
        long N = sc.nextLong();
        sc.close();

        if (N > B) {
            N = B;
        }

        long max = -1;
        for (long x = N; x >= 0; x--) {
            if (x < B - 1 && max != -1) {
                break;
            }
            long letMax = (long) (A * x / B) - A * (long) (x / B);
