	vector<int64_t>times(m,0);
	amari.at(0)=x;
	int64_t s = x;
	for(int i=1;i<m+1;i++){

		int64_t t;
		t = (s*s)%m;

		s = t;
		if(t == 0){
			flag = 1;
			j = i;
			break;
		}
		else if(t == 1){
			flag =2;
			j = i;
			break;
		}
		else{
			amari.at(i)=t;
		}
	}
	int64_t answer = 0;


	if(flag == 1){
		for(int i =0;i<j;i++){
			answer += amari.at(i);

		}
		cout << answer << endl;

	}
	else if(flag == 2){
		for(int i =0;i<j;i++){
			answer += amari.at(i);


		}
		cout << answer + n - j << endl;

	}

	else{
		for(int i=0;i<m;i++){
			int64_t c = amari.at(i);
			times.at(c)++;
		}

		int64_t d = 0;;
		for(int i = 0;i<m;i++){
			if(times.at(i)>=2){
				d = i;
				break;
			}
		}

		int64_t e,f,g,h,k;
