					e = i;
				}
				else if(count == 2){
					f = i;
				}

			}

		}

		g = f - e; 
		h = (n-e)/g;
		k = (n-e)%g;

		for(int i=e;i<f;i++){
			answer += amari.at(i);
		}
		answer *= h;
		for(int i =0;i<e;i++){
			answer += amari.at(i);

		}
		for(int i =e;i<e+k;i++){
			answer += amari.at(i);

		}

		cout << answer << endl;
	}
}

