        {
            boolean done[]=new boolean[2001];
            for(int j=3;j<=(i+1)/2;j++)
            {
                if(j>=3)
                {
                    if(i-j==j&&!done[j])
                    {
                        arr[i]=(arr[j]+arr[i])%mod;
                        done[j]=true;
                    }
                    else if(i-j>=3&&!done[j]&&!done[i-j])// if(i-j>=3&&!done[j]&&!done[i-j])
                    {
                        arr[i]+=arr[j]+arr[i-j];
                        arr[i]%=mod;
                        done[j]=done[i-j]=true;
                    }
                }
            }
        }
        pw.println(arr[s]);
        pw.flush();
        pw.close();
    }
}

