            if (i != 1)
            {
                if (e[count] != tmp)
                {
                    count++;
                }
            }
            e[count] = tmp;
        }
        M = count;
        int colortoiti[Max + 1];
        for (int i = 0; i <= Max; i++)
        {
            colortoiti[i] = 0;
        }
        for (int i = 1; i <= M; i++)
        {
            if (colortoiti[e[i]] == 0)
            {
                colortoiti[e[i]] = i;
            }
            else
            {
                beforecur[i] = colortoiti[e[i]];
                colortoiti[e[i]] = i;
            }
