		for (int i=0;i<N;i++) {
			List<Integer> x = new ArrayList<Integer>();
			edge_1.add(x);
		}
		for (int i=0;i<N-1;i++) {
			a[i]=sc.nextInt()-1;
			b[i]=sc.nextInt()-1;
			if (a[i]>b[i]) {
				int tmp=a[i];
				a[i]=b[i];
				b[i]=tmp;
			}
			edge_1.get(a[i]).add(b[i]);
			edge_1.get(b[i]).add(a[i]);
		}
		int min=0;
		for (int i=0;i<N;i++) {
			c[i]=sc.nextInt();
			min+=c[i];
		}
		Arrays.sort(c,Comparator.reverseOrder());
		min-=c[0];

		int[] ans = new int[N];
		int z = 0;

		//DFS
		Queue<int[]> queue_1 = new ArrayDeque<int[]>();
		int M = edge_1.get(0).size();
