  for (int i=0; i<sL; i++){
    if (flag) dp[i][0] = 1;
    else {
      if (s[i] == t[0]){
        flag = true;
        dp[i][0] = 1;
      }
    }
  }

  flag = false;
  for (int i=0; i<tL; i++){
    if (flag) dp[0][i] = 1;
    else {
      if (s[0] == t[i]){
        flag = true;
        dp[0][i] = 1;
      }
    }
  }

  for (int i=1; i<sL; i++){
    for (int j=1; j<tL; j++){
      if (s[i] == t[j]) dp[i][j] = dp[i-1][j-1] + 1;
      else dp[i][j] = max(dp[i-1][j], dp[i][j-1]);
    }
  }

  int i = sL-1;
  int j = tL-1;
  if (dp[i][j] == 0){
    cout << "" << endl;
    return 0;
  }

