	std::vector<std::vector<int>> tree(n);
	for (auto i = 0; i < n - 1; ++i) {
		int a, b; std::cin >> a >> b; --a; --b;
		tree[a].push_back(b);
		tree[b].push_back(a);
	}
	std::vector<int> from_takahashi(n, -1), from_aoki(n, -1);
	from_takahashi[takahashi] = from_aoki[aoki] = 0;
	std::queue<int> queue; queue.push(takahashi);
	while (!queue.empty()) {
		auto top = queue.front(); queue.pop();
		for (const auto next : tree[top]) if (from_takahashi[next] == -1) {
			from_takahashi[next] = from_takahashi[top] + 1;
			queue.push(next);
		}
	}
	queue.push(aoki);
	while (!queue.empty()) {
		auto top = queue.front(); queue.pop();
		for (const auto next : tree[top]) if (from_aoki[next] == -1) {
