        for(int j=2;j*j<=now&&flag;++j)
            if(now%j==0)
            {
                if(se.count(j)) flag=false;
                se.insert(j);
                while(now%j==0) now/=j;
            }
        if(now>1)
        {
            if(se.count(now)) flag=false;
            se.insert(now);
        }
    }
    if(flag)
    {
        cout<<"pairwise coprime"<<endl;
        return 0;
    }
    se.clear();
    int tmp=a[0];
    for(int i=2;i*i<=tmp;++i)
        if(tmp%i==0)
        {
            se.insert(i);
            while(tmp%i==0) tmp/=i;
        }
    if(tmp>1)
        se.insert(tmp);
    for(int i=1;i<n&&!flag;++i)
    {
        unordered_set<int> se_;
        int now=a[i];
        for(int j=2;j*j<=now;++j)
            if(now%j==0)
            {
                if(se.count(j)) se_.insert(j);
                while(now%j==0) now/=j;
            }
        if(now>1&&se.count(now))
            se_.insert(now);
        if(se_.empty()) flag=true;
        se=se_;
    }
    if(flag)
        cout<<"setwise coprime"<<endl;
    else
        cout<<"not coprime"<<endl;
