string s;
ll nreps;
ll f[nm][30][30];
int n;

int main() {
#ifdef LOCAL
    freopen("input.txt", "r", stdin);
#endif
    cin >> s >> nreps;
    n = s.length();
    memset(f, 0x3f, sizeof(f));
    for (int i = 0; i < 26; ++i)
    	f[0][i][i] = (s[0] == i + 'a' ? 0 : 1);
    for (int i = 1; i < n; ++i) {
    	for (int j = 0; j < 26; ++j) {
    		for (int k = 0; k < 26; ++k) {
    			int tmp = (s[i] == k + 'a' ? 0 : 1);
    			for (int u = 0; u < 26; ++u) {
    				if (u != k)
    					f[i][j][k] = min(f[i][j][k], f[i - 1][j][u] + tmp);
    			}
    		}
    	}
    }
    ll res = inf;
    if (nreps == 1) {
    	for (int i = 0; i < 26; ++i)
    		for (int j = 0; j < 26; ++j)
    			res = min(res, f[n - 1][i][j]);
    	cout << res << "\n";
    	return 0;
    }
    if (nreps == 2) {
    	for (int i = 0; i < 26; ++i) {
    		for (int j = 0; j < 26; ++j) {
				for (int u = 0; u < 26; ++u) {
					if (j == u)
						continue;
					for (int v = 0; v < 26; ++v)
						res = min(res, f[n - 1][i][j] + f[n - 1][u][v]);
				}
    		}
    	}
		cout << res << "\n";
		return 0;
    }
    for (int i = 0; i < 26; ++i) {
    	for (int j = 0; j < 26; ++j) {
    		if (f[n - 1][i][j] > n)
    			continue;
    		for (int u = 0; u < 26; ++u) {
    			if (u == j)
    				continue;
    			for (int v = 0; v < 26; ++v) {
    				if (v == i)
    					continue;
    				if (f[n - 1][u][v] > n)
    					continue;
    				res = min(res, (nreps + 1) / 2 * f[n - 1][i][j] + nreps / 2 * f[n - 1][u][v]);
    			}
    		}
    	}
    }
    for (int i = 0; i < 26; ++i) {
    	for (int j = 0; j < 26; ++j) {
    		if (f[n - 1][i][j] > n)
    			continue;
    		for (int u = 0; u < 26; ++u) {
    			if (u == j || f[n - 1][u][j] > n)
    				continue;
    			for (int v = 0; v < 26; ++v) {
    				if (f[n - 1][u][v] > n)
    					continue;
    				res = min(res, f[n - 1][i][j] + (nreps - 2) * f[n - 1][u][j] + f[n - 1][u][v]);
    			}
    		}
    	}
    }
    cout << res << "\n";
#ifdef LOCAL
    cout << (double) clock() / CLOCKS_PER_SEC << "\n";
#endif
}

