int main()
{
	int n;
	cin >> n;
	vector<long double> x(n);
	vector<long double> y(n);

	cout << setprecision(10);
	for (int i = 0; i < n; i++)
	{
		cin >> x[i] >> y[i];
	}
	long double min_of_max = 10e15;
	for (int i = 0; i < n; i++)
	{
		for (int j = i + 1; j < n; j++)
		{
			long double ux, uy;
			ux = (x[i] + x[j]) / 2;
			uy = (y[i] + y[j]) / 2;

			long double max = 0;
			for (int v = 0; v < n; v++)
			{
				long double d = sqrt((x[v] - ux) * (x[v] - ux) + (y[v] - uy) * (y[v] - uy));
				if (max < d)
					max = d;
			}
			if (max < min_of_max)
				min_of_max = max;
		}
	}
	for (int i = 0; i < n; i++)
	{
		for (int j = i + 1; j < n; j++)
		{
			for (int k = j + 1; k < n; k++)
			{
				long double a = (x[j] - x[i]) * (x[j] - x[i]) + (y[j] - y[i]) * (y[j] - y[i]); //kの対辺の長さの二乗
				long double b = (x[k] - x[i]) * (x[k] - x[i]) + (y[k] - y[i]) * (y[k] - y[i]); //jの対辺の長さの二乗
				long double c = (x[j] - x[k]) * (x[j] - x[k]) + (y[j] - y[k]) * (y[j] - y[k]); //iの対辺の長さの二乗

				long double ux, uy;

				if (a * (b + c - a) + b * (c + a - b) + c * (a + b - c) == 0)
				{
					if (a >= b && a >= c)
					{
						ux = (x[j] + x[i]) / 2;
						uy = (y[j] + y[i]) / 2;
					}
					if (b >= a && b >= c)
					{
						ux = (x[k] + x[i]) / 2;
						uy = (y[k] + y[i]) / 2;
					}
					if (c >= a && c >= b)
					{

						ux = (x[k] + x[j]) / 2;
						uy = (y[k] + y[j]) / 2;
					}
				}
				else
				{
					ux = (a * (b + c - a) * x[k] + b * (c + a - b) * x[j] + c * (a + b - c) * x[i]) / (a * (b + c - a) + b * (c + a - b) + c * (a + b - c));
					uy = (a * (b + c - a) * y[k] + b * (c + a - b) * y[j] + c * (a + b - c) * y[i]) / (a * (b + c - a) + b * (c + a - b) + c * (a + b - c));
				}

				long double max = 0;
				for (int v = 0; v < n; v++)
				{
					long double d = sqrt((x[v] - ux) * (x[v] - ux) + (y[v] - uy) * (y[v] - uy));
					if (max < d)
						max = d;
				}
				if (max < min_of_max)
					min_of_max = max;
			}
		}
	}
	cout << min_of_max << endl;
}

