		}
		for(int i = 0; i<Math.pow(2,n); i++){
			for(int j = 0; j<Math.pow(2,n); j++){
				int t=i;
				int y=j;
				int cost=0;
				int a1=0;
				int b1=0;
				int c1=0;
				for(int k=0; k<n; k++){
					if((t & 1)==1 && (y & 1)==1){
						if(a1!=0){
							cost+=10;
						}
						a1+=d[k]; 
					}else if((t & 1)==0 && (y & 1)==1){
						if(b1!=0){
							cost+=10;
						}
						b1+=d[k];
					}else if((t & 1)==1 && (y & 1)==0){
						if(c1!=0){
