using namespace std;
using ll = long long int;
using lc = complex<double>;

int main(void) {
    constexpr ll MOD = 998244353;
    constexpr double PI = acos(-1);
    cout << fixed << setprecision(32);
    cin.tie(0); ios::sync_with_stdio(false);


    ll n, s;
    cin >> n >> s;
    vector<ll> a(n);
    for(auto &e: a) cin >> e;
    vector<vector<ll>> dp(n+1, vector<ll>(s+1));
    vector<vector<ll>> dq(n+1, vector<ll>(s+1));
    dp[0][0] = 1;
    for(ll i=1; i<=n; i++)
        for(ll j=0; j<=s; j++) {
            (dp[i][j] = dp[i-1][j] * 2) %= MOD;
            if(j-a[i-1]>=0)
                (dp[i][j] += dp[i-1][j-a[i-1]]) %= MOD;
        }

    dq[n][0] = 1;
    for(ll i=1; i<=n; i++)
        for(ll j=0; j<=s; j++) {
            dq[n-i][j] = dq[n+1-i][j];
            if(j-a[i-1]>=0)
                (dq[n-i][j] += dq[n+1-i][j-a[i-1]]) %= MOD;
        }


    ll res = dp[n][s];
    cout << res << endl;
    for(ll t=0; t<=s; t++) {
        for(ll i=1; i<=n; i++) {
            (res += dp[i-1][s-t] * dq[n+1-i][t]) %= MOD;
        }

    }
}

