        for (int i = 0 ; i < m ; i++) {
            a[i] = sc.nextInt() - 1;
            b[i] = sc.nextInt() - 1;
        }
        Set<Long> pair = new HashSet<>();
        for (int i = 0 ; i < m ; i++) {
            pair.add((long) a[i] * 100000 + b[i]);
        }
        int[] c = new int[h];
        int[] d = new int[w];
        for (int i = 0 ; i < m ; i++) {
            c[a[i]]++;
            d[b[i]]++;
        }
        int hmax = 0;
        int wmax = 0;
        for (int i = 0 ; i < h ; i++) {
            if (c[i] > hmax) {
                hmax = c[i];
            }
        }
        for (int i = 0 ; i < w ; i++) {
            if (d[i] > wmax) {
                wmax = d[i];
            }
        }
        Set<Integer> seth = new HashSet<>();
        Set<Integer> setw = new HashSet<>();
        for (int i = 0 ; i < h ; i++) {
            if (c[i] == hmax) {
                seth.add(i);
            }
