  tmp_count = 0;
  for(ll i = 0; i < N; i++){
    if(S[i] == 'o' && i > tmp_pos+C){
      tmp_count++;
      tmp_pos = i;
    }
    dp1[i] = tmp_count;
  }

  cerr << "dp1:" << endl;
  for(ll i = 0; i < N; i++){
