  }cerr << endl;

  tmp_pos = N+C;
  tmp_count = 0;
  for(ll i = N-1; i >= 0; i--){
    if(S[i] == 'o' && i < tmp_pos-C){
      tmp_count++;
      tmp_pos = i;
    }
    dp2[i] = tmp_count;
  }

  cerr << "dp2: " << endl;
  for(ll i = 0; i < N; i++){
