using namespace std;

#define INF 10000000000000007

int main()
{
	long long n,m,s,t;
	cin >> n >> m >> s >> t;
	s--;t--;
	vector<vector<pair<long long,long long>>> to1(n);
	vector<vector<pair<long long,long long>>> to2(n);
	for(long long i=0;i<m;i++)
	{
		long long u,v,a,b;
		cin >> u >> v >> a >> b;
		u--;v--;
		to1[u].push_back(make_pair(v,a));
		to1[v].push_back(make_pair(u,a));
		to2[u].push_back(make_pair(v,b));
		to2[v].push_back(make_pair(u,b));
	}
	vector<long long> dist1(n,INF);
	vector<long long> dist2(n,INF);
	vector<bool> done(n,false);
	dist1[s]=0;
	priority_queue<pair<long long,long long>> que;
	que.push(make_pair(-1*0,s));
	int cnt=0;
	while(!que.empty())
	{
		auto now=que.top();
		que.pop();
		long long nowid=now.second;
		long long nowdis=now.first*(-1);
		if(done[nowid])continue;
		dist1[nowid]=min(dist1[nowid],nowdis);
		done[nowid]=true;
		cnt++;
		if(cnt>=n)break;
		for(long long i=0;i<to1[nowid].size();i++)
		{
			auto nx=to1[nowid][i];
			long long nxid=nx.first;
			long long nxdis=nx.second;
			if(done[nxid]==true)continue;
			que.push(make_pair(-1*(nxdis+nowdis),nxid));
		}
	}

	while(!que.empty())
		que.pop();

	done=vector<bool>(n,false);
	dist2[t]=0;
	que.push(make_pair(-1*0,t));
	cnt=0;
	while(!que.empty())
	{
		auto now=que.top();
		que.pop();
		long long nowid=now.second;
		long long nowdis=now.first*(-1);
		if(done[nowid])continue;
		dist2[nowid]=min(dist2[nowid],nowdis);
		done[nowid]=true;
		cnt++;
		if(cnt>=n)break;
		for(long long i=0;i<to2[nowid].size();i++)
		{
			auto nx=to2[nowid][i];
			long long nxid=nx.first;
			long long nxdis=nx.second;
			if(done[nxid]==true)continue;
			que.push(make_pair(-1*(nxdis+nowdis),nxid));
		}
	}

	for(long long i=0;i<n;i++)
		cerr << dist1[i] << (i==n-1 ? "\n":" ");

	for(long long i=0;i<n;i++)
		cerr << dist2[i] << (i==n-1 ? "\n":" ");

	vector<long long> ans(n);
	for(long long i=0;i<n;i++)
	{
		ans[i]=dist1[i]+dist2[i];
	}
	long long mn=INF;
	for(long long i=n-1;i>=0;i--)
	{
		if(ans[i]>mn)
			ans[i]=mn;
		else
			mn=ans[i];
	}
	for(long long i=0;i<n;i++)
		cout << 1000000000000000-ans[i] << endl;

}

