                cin >> s[i];
            }

            int total;
            double ave;
            double a2;

            total = 0;
            for (int i = 0; i < n; i++) {
                total += s[i]; 
            }
            ave = (double)total / n;    // 平均値

            a2 = 0;
            for (int i = 0; i < n; i++) {
                double tmp = ((double)s[i] - ave);
                a2 += tmp * tmp;
            }

            delete [] s;

            a2 /= n;

            long double a = sqrt(a2);   // 標準偏差

            cout << setprecision(16) << a << endl;
        }
        catch (...) {
            continue;
        }
    }

    return 0;
