typedef pair<int, int> P;
int INF = 2'000'000'000;

int main(){
    int n, m;
    cin >> n >> m;
    vector<vector<int>> edge(n);
    int u, v;
    for (int i = 0; i < m; i++){
        cin >> u >> v;
        u--; v--;
        edge[u].push_back(v);
    }
    int s, t;
    cin >> s >> t;
    s--; t--;
    vector<vector<int>> distance(n, vector<int>(3, INF));
    vector<vector<bool>> check(n, vector<bool>(3, false));
    priority_queue<P, vector<P>, greater<P>> que;
    que.push({0, s});

    for (int i = 0; i < 3*m; i++){
        if (que.size() == 0) break;
        int x = que.top().first;
        int y = que.top().second;
        que.pop();
        if (y == t && x % 3 == 0){
            cout << x / 3 << endl;
            exit(0);
        }
        if (distance[t][2] != INF) break;
        for (int j = 0; j < 3; j++){
            if (distance[y][j] > x) {
                if (j == 0) {
                    distance[y][j] = x;
                    check[y][j] = true;
                    break;
                }
                else if (j == 1 && distance[y][0] % 3 != x % 3){
                    distance[y][j] = x;
                    check[y][j] = true;
                    break;
                }
                else if (j == 2 && distance[y][0] % 3 != x % 3 && distance[y][1] % 3 != x % 3){
                    distance[y][j] = x;
                    check[y][j] = true;
                    break;
                }
            }
        }
        int k = (int)edge[y].size();
        for (int pp = 0; pp < 3; pp++){
            if (!check[y][pp]) continue;
            int nx = distance[y][pp] + 1;
            for (int j = 0; j < k; j++){
                int ny = edge[y][j];
                que.push({nx, ny});
            }
        }

        for (int pp = 0; pp < 3; pp++){
            check[y][pp] = false;
        }
    }
    cout << -1 << endl;
}

