  for (int i=0; i<n; i++) exist[n] = false;

  bool c[m][n];
  for (int i=0; i<m; i++) {
    for (int j=0; j<n; j++) {
      c[i][j] = false;
    }
  }
  for (int i=0; i<m; i++) {
    cin>>a[i]>>b[i];
    for (int j=0; j<b[i]; j++) {
      int cij;
      cin>>cij;
      --cij;
      exist[cij] = true;
      c[i][cij] = true;
    }
  }
  for (int i=0; i<n; i++) {
    if (!exist[i]) {
      cout<<-1<<endl;
      return 0;
    }
  }
  int size = 1 << n;
  long long d[size];
  for (int i=0; i<size; i++) d[i] = 1e10;
  for (int i=0; i<m; i++) {
    int idx = 0;
    for (int j=0; j<n; j++) {
      if (c[i][j]) {
        idx += (1 << j);
      }
    }
    d[idx] = min((long long)a[i], d[idx]);
  }
  while (true) {
    bool updated = false;
    for (int i=0; i<size; i++) {
      for (int j=0; j<size; j++) {
        if (i == j) {
          continue;
        }
        if (d[i] == 1e10 || d[j] == 1e10) {
          continue;
        }
        int idx = 0;
        for (int k=0; k<n; k++) {
          if (((i >> k) | (j >> k)) & 1) {
            idx += (1 << k);
          }
        }
        if (d[idx] > d[i] + d[j]) {
          updated = true;
          d[idx] = d[i] + d[j];
        }
      }
    }
    if (!updated) {
      break;
    }
  }
  cout<<d[size-1]<<endl;
}

