    ll tmp = 0, number = 1;
    A[disjoint_list[i].first][disjoint_list[i].second] = -1;
    while (!que.empty()) {
      P p = que.front();
      que.pop();
      int y = p.first, x = p.second;
      if (x > 0) {
        int ny = y, nx = x - 1;
        if (S[y][x] != S[ny][nx] && A[ny][nx] != -1) {
          if (S[ny][nx] == '#')
            number++;
          else
            tmp++;
          A[ny][nx] = -1;
          que.push(P(ny, nx));
        }
      }
      if (x < W - 1) {
        int ny = y, nx = x + 1;
        if (S[y][x] != S[ny][nx] && A[ny][nx] != -1) {
          if (S[ny][nx] == '#')
            number++;
          else
            tmp++;
          A[ny][nx] = -1;
          que.push(P(ny, nx));
        }
      }
      if (y > 0) {
        int ny = y - 1, nx = x;
        if (S[y][x] != S[ny][nx] && A[ny][nx] != -1) {
          if (S[ny][nx] == '#')
            number++;
          else
            tmp++;
          A[ny][nx] = -1;
          que.push(P(ny, nx));
        }
      }
      if (y < H - 1) {
