  ld a,b,x;
  cin >> a >> b >> x;

  ld V = a * a * b;
  ld theta;
  if (x <= V / 2.0) {
    ld Left = 0;
    ld Right = PI / 2.0;
    while (true) {
      ld pivot = (Left + Right) / 2.0;
      if (a*b*b  * tan(PI / 2 - pivot) / 2 > x) Left = pivot;
      else if (a*b*b * tan(PI / 2 - pivot) / 2 < x) Right = pivot;
      else {
        theta = pivot;
        break;
      }
      if (abs(a*b*b * tan(PI / 2 - pivot) / 2 - x) < 0.000000001) {
        theta = pivot;
        break;
      }
    }
  } else if (x > V / 2.0) {
    ld Left = 0;
    ld Right = PI / 2.0;
    while (true) {
      ld pivot = (Left + Right) / 2.0;
      if (a*a*a * tan(pivot) / 2 > (V - x)) Right = pivot;
      else if (a*a*a * tan(pivot) / 2 < (V - x)) Left = pivot;
      else {
        theta = pivot;
        break;
      }
      if (abs(a*a*a * tan(pivot) / 2 - (V - x)) < 0.000000001) {
        theta = pivot;
        break;
      }
    }
  }

  theta = theta * 180 / PI;

