{
	int x=0,y=0;
	cin >> x >> y;
	if ((x+y)%3!=0)
	{
		cout << 0;
		return 0;
	}		
	int m = (2*y-x)/3;	
	if ((2*y-x)<0 || (2*y-x)%3!=0)
	{
		cout << 0;
		return 0;
	}
	int n = (x-m)/2;		
	if ((x-m)<0 || (x-m)%2!=0)
	{
		cout << 0;
		return 0;
	}
	for (int i=n+1; i<=n+m; i++)
	{
		int ii = i;
		while (ii%2==0)
		{
			ii/=2;
			Map[2]++;
		}
		int sqrtII = round(sqrt(ii));
		for (int j=3; j<=sqrtII; j+=2)
		{
			while (ii%j==0)
			{
				ii/=j;
				Map[j]++;
			}
		}
		if (ii!=1)
			Map[ii]++;
	}
	for (int i=2; i<=m; i++)
	{
		int ii = i;
		while (ii%2==0)
		{
			ii/=2;
			Map[2]--;
		}
		int sqrtII = round(sqrt(ii));
		for (int j=3; j<=sqrtII; j+=2)
		{
			while (ii%j==0)
			{
				ii/=j;
				Map[j]--;
			}
		}
		if (ii!=1)
			Map[ii]--;
	}
	int res=1;
	for (int i=2; i<=1000000; i++)
	{
		for (int j=1; j<=Map[i]; j++)
		{
			res = (res*i)%MOD;
		}
	}	
	cout << res;
	return 0;
}

