		for(int i=0;i<20;i++) {
			dual[i][0]=0;
		}
		for(int i = 0;i<n;i++) {
			for(int j = 0;j<20;j++) {
				if(Math.pow(2, 19-j)<=a[i]) {
					dual[j][i+1]=1;
					a[i]-=Math.pow(2, 19-j);
				}else {
					dual[j][i+1]=0;
				}
			}
		}
		for(int i = 1;i<n+1;i++) {
			for(int j = 0;j<20;j++) {
