                if (d[i].second) {
                    u1 = i;
                    break;
                }
            }
            for (int i = k; i < n; i++) if (!d[i].second) {
                v1 = i;
                break;
            }
            for (int i = k - 1; i >= 0; i--) {
                if (!d[i].second) {
                    u2 = i;
                    break;
                }
            }
            for (int i = k; i < n; i++) if (d[i].second) {
                v2 = i;
                break;
            }
            if ((u2 == -1 || v2 == -1) || (v1 != -1 && u1 != -1 && d[v1].first * d[u2].first > d[v2].first * d[u1].first)) {
                for (int i = 0; i < n; i++) {
                    if (i < k) {
                        if (i != u1) z *= d[i].first, z %= mod;
                    } else {
