                    }
                }
            } else {
                for (int i = 0; i < n; i++) {
                    if (i < k) {
                        if (i != u2) z *= d[i].first, z %= mod;
                    } else {
                        if (i == v2) z *= d[i].first, z %= mod;
                    }
                }
            }
        }
    }
    cout << z;
