#include <bits/stdc++.h>
#define ll long long
#define rep(X,N) for(ll X = 0; X < (N); X++)
#define bitrep(X,N) for(ll X = 0; X < (1 << (N)); X++)
#define PI (acos(-1.0))
#define sorta(V) sort(V.begin(), V.end())
#define pback push_back
#define mpair make_pair
#define MODN 1000000007
#define ALL(V) (V).begin(),(V).end() 


using namespace std;


int main(){

    vector<int> prime;

    function<void(int)> sieve = [&](int n) -> void{

        //assert(n >= 2);

        vector<int> p;

        for(int i = 0; i <= n; i++){
            p.push_back(1);
        }


        p[0] = 0;
        p[1] = 0;

        for(int i = 2; i <= n; i++){
            if(i * i > n){
                break;
            }

            if(p[i] == 1){
                for(int j = i * i; j <= n; j = j + i){
                    p[j] = 0;
                }
            }
        }

        for(int i = 2; i <= n; i++){
            if(p[i] == 1) prime.push_back(i);
        }
    };

    function<int(int, int, int)> powmod = [&](int ai, int xi, int pi) -> int{


            if(xi == 0){
                return 1;
            }else if(xi % 2 == 1){
                return (((ll)ai) * powmod(ai, xi - 1, pi)) % pi;
            }else{
                ll tmp = powmod(ai, xi/2, pi);
                return (tmp * tmp) % pi;
            }

    };

    function<int(int,int)> invmod = [&](int a, int p) -> int{

        assert(p > 1);

        return powmod(a, p - 2, p) % MODN;
    };

    int n,m;
    cin >> n >> m;

    sieve(ceil(sqrt(m)));

    vector<ll> fact;
    fact.pback(1);

    for(int i = 1; i <= n + 35; i++){
        fact.pback((fact[i - 1] * i) % MODN);
    }

    vector<int> factor(prime.size());
    int tmp = m;

    ll ans = 1;

    while(tmp >= 2){
        bool b = true;
        rep(i,prime.size()){
            if(tmp % prime[i] == 0){
                tmp = tmp / prime[i];
                factor[i]++;
                b = false;
                break;
            }
        }

        if(b){
            ans = n;
            break;
        }
    }

    if(n - 1 > 0){
        rep(i,factor.size()){
            if(factor[i] > 0){

                ll tmp = 1;

                tmp = (tmp * fact[factor[i] + n - 1]) % MODN;
                tmp = (tmp * invmod(fact[n - 1], MODN)) % MODN;
                tmp = (tmp * invmod(fact[factor[i]], MODN)) % MODN;

                ans = (ans * tmp) % MODN;

            }
        }
    }

    cout << ans << endl;

    return 0;
}

