#include <bits/stdc++.h>
#include <boost/range/irange.hpp>
#include <boost/range/adaptors.hpp>

using namespace std;
using boost::adaptors::reversed;
using boost::irange;
using uint = unsigned int;
using ll = long long int;
using ull = unsigned long long int;

int main() {
    ll N, M, Q;
    cin >> N >> M >> Q;
    vector<pair<ll, ll>> lrs{}, pqs{};
    for (auto &&i: irange(0LL, M)) {
        ll l, r;
        cin >> l >> r;
        l--; r--;
        lrs.emplace_back(make_pair(l, r));
    }
    for (auto &&i: irange(0LL, Q)) {
        ll p, q;;
        cin >> p >> q;
        p--; q--;
        pqs.emplace_back(make_pair(p, q));
    }
    vector<vector<ll>> from_to(N, vector<ll>(N, 0));
    for (auto && i: irange(0LL, M)){
        ll from, to;
        tie(from, to) = lrs.at(i);
        from_to.at(from).at(to)++;
    }
//    from_toに対して範囲クエリが飛んでくる
//    from_toのこの範囲の合計は？みたいなクエリ
//    1次元であれば，累積和をとって，先っちょマイナスお尻でいける
//    2次元であれば，累積和の特殊系を作って，解く
//    ポイントは累積和の上下のおしりを0で埋めること
//    つまり，acc[i+1] = acc[i] + raw[i]というふうには書けないということを自覚すること
//    （acc[i+1, j]+=acc[i, j]; acc[i, j+1]+=acc[i, j]と書く）

//    初期化
    vector<vector<ll>> acc(N+1, vector<ll>(N+1, 0));
    for (auto && i: irange(1LL, N+1)){
        for (auto && j: irange(1LL, N+1)){
            acc.at(i).at(j) = from_to.at(i-1).at(j-1);
        }
    }
//    行方向の和
    for (auto && i: irange(1LL, N+1)){
        for (auto && j: irange(0LL, N+1)){
            acc.at(i).at(j) += acc.at(i-1).at(j);
        }
    }
//    列方向の和
    for (auto && i: irange(0LL, N+1)){
        for (auto && j: irange(1LL, N+1)){
            acc.at(i).at(j) += acc.at(i).at(j-1);
        }
    }
//    範囲クエリに答える
//    添字が1ずつずれている(つまり，pqの世界でのiはaccの世界でのi+1)
    for (auto && i: irange(0LL, Q)){
        ll p, q;
        tie(p, q) = pqs.at(i);
        cout << acc.at(q+1).at(q+1) - acc.at(q+1).at(p) - acc.at(p).at(q+1) + acc.at(p).at(p) << endl;
    }

    return 0;
}

