    while (i!=N && j!=N) {
        if (B[i]==C[j]) {
            if (i==N-1 && j==N-1) {
                x++;
                break;
            }
            if (i==N-1) {
                x++; j++;
            }
            else if (j==N-1) {
                x++; i++;
            }
            else if (B[i+1]==C[j+1]) {
                I=i; J=j;
                while (1) {
                    if (I!=N-1 && B[I+1]==B[i]) I++;
                    else break;
