        int[][] a = new int[n*2][3];
        for (int i = 0; i < n; i++) {
            int s = sc.nextInt();
            int t = sc.nextInt();
            int x = sc.nextInt();
            a[i+n][0] = s - x;
            a[i+n][1] = 1;
            a[i+n][2] = x;
            a[i][0] = t - x;
            a[i][1] = -1;
            a[i][2] = x;
        }
        Arrays.sort(a, (x, y) -> x[0] - y[0]);
        int[] d = new int[q];
        for (int i = 0; i < q; i++) {
            d[i] = sc.nextInt();
        }
        int[] ans = new int[q];
