        for (int i = 0; i < n*2; i++) {
            while(idx < q && d[idx] < a[i][0]){
                if(set.isEmpty()) ans[idx] = -1;
                else ans[idx] = set.first();
                idx++;
            }
            if(idx == q) break;
            if(a[i][1] == 1){
                set.add(a[i][2]);
            }else{
