    for (int i = 0; i < n; ++i) {
        int a,b,c;
        cin>>a>>b>>c;
        d[i]=make_pair(c,make_pair(a,b));
    }
    sort(d.begin(),d.end());
    for (int i = 0; i < q; ++i) {
        cin>>p[i];
    }

    vector<int> ans(q,-1);
    int safel=-1;
    int safer=q;
    for (int i = 0; i < n; ++i) {
        if(safel>=q-1)break;
        if(safer<=0)break;
        int okl=safel;
        int ngl=q;
        int midl=(okl+ngl)/2;
        while((ngl-okl)!=1){
            midl=(okl+ngl)/2;
            if(p[midl]+d[i].first<d[i].second.first)okl=midl;
            else ngl=midl;
        }

        int okr=safer;
        int ngr=-1;
        int midr=(okr+ngr)/2;
        while((okr-ngr)!=1){
            midr=(okr+ngr)/2;
            if(p[midr]+d[i].first>=d[i].second.second)okr=midr;
            else ngr=midr;
        }

        for (int j = ngl; j <= ngr; ++j) {
            if(ans[j]==-1)ans[j]=d[i].first;
        }
        while(1){
            if(safel>=q)break;
            if(ans[safel+1]!=-1)++safel;
            else break;
        }
        while(1){
            if(safer<=0)break;
            if(ans[safer-1]!=-1)--safer;
            else break;
        }
