                 if(g[i][k]!=inf &&g[k][j]!=inf &&g[i][k]+g[k][j]<g[i][j])
                    g[i][j]=g[i][k]+g[k][j];
    bool negative=false;
     for(i=0;i<n;i++)
        for(j=0;j<n;j++)
            if(g[i][j]!=g_[i][j])
                negative=true;
    if(negative)
        cout<<"NEGATIVE CYCLE"<<endl;
    else{
        for(i=0;i<n;i++){
            for(j=0;j<n-1;j++)
                if(g[i][j]==inf)
                    cout<<"INF ";
                else
