            int tmp = (l + r) / 2;

            int b = tmp;
            long ans = 0;
            for (int i = 0; i < n; i++) {
                ans += Math.abs(a[i] - 1 - i - b);
            }

            b = tmp + 1;
            long ans2 = 0;
            for (int i = 0; i < n; i++) {
                ans2 += Math.abs(a[i] - 1 - i - b);
            }

            b = tmp - 1;
            long ans3 = 0;
            for (int i = 0; i < n; i++) {
                ans3 += Math.abs(a[i] - 1 - i - b);
