		} // end for
		double CX = *(Cx.begin() );
		double CY = *(Cy.begin() );
		double R = sqrt( (CX - X[0])*(CX - X[0]) + (CY - Y[0])*(CY - Y[0]) );

		cout.setf( ios::fixed ); 
		cout.precision(3);
		cout <<  CX << ' ' << CY << ' ' << R << endl;
 	} // end for


