#include<cmath>
using namespace std;

int main() {
    long n, a, b;
    cin>>n>>a>>b;
    long nn = n;
    long ans = 1;
    while(n!=0){
        long tmp=1;
        long tmpans = 2;
        while(true){
            tmp *= 2;
            if(tmp>n){
                tmp /= 2;
                break;
            }
            tmpans *= tmpans;
            tmpans %= 1000000007;
        }
        ans *= tmpans;
        ans %= 1000000007;
        n -= tmp;
    }

    long ans1 = 1;
    long ans2 = 1;
    for(int i=0;i<a;++i){
        ans1 *= nn-i;
        ans1 %= 1000000007;
    }
    for(int i=0;i<b;++i){
        ans2 *= nn-i;
        ans2 %= 1000000007;
    }
    long a1 = 1;
    long b1 = 1;
    for(int i=0;i<a;++i){
        a1 *= a-i;
        a1 %= 1000000007;
    }
    for(int i=0;i<b;++i){
        b1 *= b-i;
        b1 %= 1000000007;
    }
    long ans11 = 1;
    long ans22 = 1;
    long p1 = 1000000005;
    long p2 = 1000000005;
    while(p1!=0){
        long tmp=1;
        long tmpans = a1;
        while(true){
            tmp *= 2;
            if(tmp>p1){
                tmp /= 2;
                break;
            }
            tmpans *= tmpans;
            tmpans %= 1000000007;
        }
        ans11 *= tmpans;
        ans11 %= 1000000007;
        p1 -= tmp;
    }
    while(p2!=0){
        long tmp=1;
        long tmpans = b1;
        while(true){
            tmp *= 2;
            if(tmp>p2){
                tmp /= 2;
                break;
            }
            tmpans *= tmpans;
            tmpans %= 1000000007;
        }
        ans22 *= tmpans;
        ans22 %= 1000000007;
        p2 -= tmp;
    }
    ans -= 1 + (ans1*ans11)%1000000007 + (ans2*ans22)%1000000007;
    while (ans < 0) {
        ans += 1000000007;
    }
    cout<<ans%1000000007<<endl;
}

