long long n, m, k;
long long ta[100000];
long long x[100000];
long long l[100000];
long long c[100000];
long long b[100000];
long long dp[100000];
long long le, ri, md, dpp;
int main() {
	scanf("%lld", &n);
	for (long long i = 0; i < n; i++) {
		scanf("%lld%lld", x + i, l + i);
		c[i] = x[i] + l[i];
		c[i] *= 1000000001;
		c[i] += l[i];
	}
	std::sort(c, c + n);
	for (long long i = 0; i < n; i++) {
		l[i] = c[i] % 1000000001;
		b[i] = c[i] / 1000000001;
		c[i] /= 1000000001;
	}
	m = n;
	for (long long i = 1; i < n; i++) {
		if (c[i] == c[i - 1]) {
			c[i - 1] = 100000;
			c[i - 1] *= 100000;
			m--;
		}
	}
	std::sort(c, c + n);
	for (long long i = 0; i < n; i++) {
		while (c[k] < b[i])k++;
		ta[i] = k;
	}
	for (long long i = 0; i < n; i++) {
		if (ta[i]) {
			if (dp[ta[i]] < dp[ta[i] - 1]) {
				dp[ta[i]] = dp[ta[i] - 1];
			}
		}
		le = -1;
		ri = m - 1;
		while (ri - le > 1) {
			md = (ri + le) / 2;
			if (c[md] <= b[i] - 2 * l[i])le = md;
			else ri = md;
		}
		dpp = 1;
		if (le != -1) {
			dpp += dp[le];
		}
		if (dp[ta[i]] < dpp)dp[ta[i]] = dpp;
	}
	printf("%lld\n", dp[m - 1]);
}

