using namespace std;

const long long NUM = 1000000007;

int main(){
	int N,K;
	cin>>N>>K;
	vector<vector<long long> >C;
	for(int i=0;i<3000;++i){
		vector<long long>tmpC;
		for(int j=0;j<i+1;++j){
			if(j==0 || j==i)tmpC.push_back(1);
			else{
				tmpC.push_back(C[C.size()-1][j-1]%NUM + C[C.size()-1][j]%NUM);
			}
		}
		C.push_back(tmpC);
	}
	long long ans[K+1];
	if(N==K){
		for(int i=0;i<K;++i){
			if(i==0)cout<<1<<endl;
			else cout<<0<<endl;
		}
	}
	else{
		for(int i=0;i<K;++i){
			if(i==0){
				ans[i] = N-K+1;
			}
			else{
				if(N-K>i+1){
					ans[i] = ((C[N-K-1][i+1]%NUM)*(C[K-1][i]%NUM))%NUM + 2*((C[N-K-1][i]%NUM)*(C[K-1][i]%NUM))%NUM + ((C[N-K-1][i-1]%NUM)*(C[K-1][i]%NUM))%NUM;
				}
				else if(N-K==i+1){
					ans[i] = 2*(C[N-K-1][i]%NUM)*(C[K-1][i]%NUM)%NUM + (C[N-K-1][i-1]%NUM)*(C[K-1][i]%NUM)%NUM;
				}
				else if(N-K==i){
					ans[i] = (C[N-K-1][i-1]%NUM)*(C[K-1][i]%NUM)%NUM;
				}
				else{
					ans[i] = 0;
				}
			}
		}
		for(int i=0;i<K;++i){
			cout<<ans[i]%NUM<<endl;
		}
	}
	/*
	for(int i=0;i<C.size();++i){
		for(int j=0;j<C[i].size();++j){
			cout<<C[i][j]<<" ";
		}
		cout<<endl;
	}
	cout<<endl;
	*/
}

