class Program
{
    static void Main(string[] args)
    {
            // 入力
            string[] sS = Console.ReadLine().Split(' ');
            int iN = int.Parse(sS[0]);
            sS = Console.ReadLine().Split(' ');
            List<int> lstA = new List<int>();
            for (int i = 0; i < sS.Length; i++) { lstA.Add(int.Parse(sS[i])); }

            System.Diagnostics.Stopwatch sw = new System.Diagnostics.Stopwatch();
            sw.Start();

            // 解析
            lstA.Sort();                                                                                // 一応昇順
            int iMax = lstA[lstA.Count - 1];                                                            // nCrのnはすぐ判明
            int iMid = iMax / 2;                                                                        // nCrのrはこの値が最大だか数列内存在するかは不明
            if (lstA.Count == 2) { iMid = lstA[0]; iMax = lstA[1]; }                                    // 2つしかない場合 固定
            else                                                                                        // 3つ以上  数列内でrに近い値をどうにか取得
            {
                List<ClsPot> lstPot = new List<ClsPot>();
                for (int i = 0; i < lstA.Count - 1; i++)                                                // lstA.Count - 1 まで。最後のはiMaxで確定済み
                {
                    lstPot.Add(new ClsPot() { iX = lstA[i], iD = Math.Abs(iMid - lstA[i]) });           // 値とrまでの差
                }
                lstPot.Sort(delegate (ClsPot mca1, ClsPot mca2) { return (int)(mca1.iD - mca2.iD); });  // iDの昇順
                iMid = lstPot[0].iX;                                                                    // rまでの差が一番小さいの
                if (lstPot[0].iD == lstPot[1].iD) { iMid = lstPot[0].iX > lstPot[1].iX ? lstPot[0].iX : lstPot[1].iX; } // 2番目に小さいのも同じ差ならXの大きいの
            }

            // 出力
            Console.WriteLine("{0} {1}", iMax.ToString().Trim(), iMid.ToString().Trim());

            sw.Stop();
#if DEBUG
            Console.WriteLine();
            Console.WriteLine("{0}", sw.Elapsed.ToString());
            Console.WriteLine("続行するには何かキーを押してください．．．");
            Console.ReadKey();
#endif
    }

        // 点位置情報
        private class ClsPot
        {
            public int iX { get; set; } = -1;                        // 値
            public int iD { get; set; } = -1;                        // rとの差
        }

}

