class ALDS1
{
    static int isprime(int x)
    {
        if (
            x == 2 ||
            x == 3 ||
            x == 5 ||
            x == 7 ||
            x == 11 ||
            x == 13 ||
            x == 17 ||
            x == 19
            ) return 1;
        else if (
            x == 1 ||
            x % 2 == 0 ||
            x % 3 == 0 ||
            x % 5 == 0 ||
            x % 7 == 0 ||
            x % 11 == 0 ||
            x % 13 == 0 ||
            x % 17 == 0 ||
            x % 19 == 0
        ) return 0;
        else if (x < 100000)
        {
            for (int i = 23; i < x; i += 2)
            {
                if (x % i == 0) return 0;
            }
        }
        else if (x >= 100000)
        {
            for (int i = 23; i * i < x; i += 2)
            {
                if (x % i == 0) return 0;
            }
        }
        return 1;
