        int[] total = new int[31];
        for(int i=0; i<N; i++) {
            long num = sc.nextLong();
            int count = 0;
            while(num>1) {
                int remain = (int) (num % 2);
                nums[i][count] = remain;
                num -= remain;
                num/=2;
                if(total[count]==remain) {
                    total[count]=0;
                }else {
                    total[count]=1;
                }
                count++;
            }
            if(num==0) {
                nums[i][count]=0;
            }else {
                nums[i][count] = 1;
            }
            if(total[count]==nums[i][count]) {
                total[count]=0;
            }else {
                total[count]=1;
            }
