				int me = 0;
				int c = me * 2 + 1;
				while (c < n) {
					if (c != n - 1 && heap[c].b < heap[c + 1].b) {
						++c;
					}

					if (item.b < heap[c].b) {
						heap[me] = heap[c];
						me = c;
						c = c * 2 + 1;
					} else {
						break;
					}
				}

				heap[me] = item;
				--count;

				return ret;
			}


			long ans = 0;
			for (int i = m; i >= 0; i--) {
				while (q.Count > 0 && m - i >= q.Peek().a) {
					Enqueue(q.Dequeue());
				}

				if (count > 0) {
					var next = Dequeue();
					ans += next.b;
				}
			}

			Console.WriteLine(ans);
		}
	}
}

