    class Program
    {
        public static int n = 0;
        public static int[] P;
        public static int[] I;
        public static int pos=0;
        public static void Recon(int left, int right, List<int>A)
        {
            if (left >= right) return;
            int root = P[pos++];
            int m = 0;
            //mはinternal node
            for(int i=0; i<n; i++)
            {
                if (root == I[i]) m= i;
            }
            Recon(left, m, A);
            Recon(m+1, right,A);
            A.Add(root);
