    {
        struct Edge
        {
            public int to;
            public int cost;
        }

        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var graph = new Edge[n][];

            for (int i = 0; i < n; i++)
                graph[i] = Console.ReadLine().Trim(' ').Split(' ')
                    .Skip(2)
                    .Select((s, index) => new { val = int.Parse(s), index})
                    .GroupBy(x => x.index / 2)
                    .Select(group => group.Select(g => g.val))
                    .Select(vc => new Edge { to = vc.First(), cost = vc.Last() })
                    .ToArray();

            var used = new bool[n];
            var mincost = Enumerable.Repeat(int.MaxValue, n).ToArray();
            mincost[0] = 0;

            while (true)
            {
                var v = -1;
                for (int i = 0; i < n; i++)
                    if (!used[i] && (v == -1 || mincost[i] < mincost[v])) v = i;

                if (v == -1) break;
                used[v] = true;

                for (int i = 0; i < graph[v].Length; i++)
                    mincost[graph[v][i].to] = Math.Min(mincost[graph[v][i].to], mincost[v] + graph[v][i].cost);
            }

            for (int i = 0; i < mincost.Length; i++)
                Console.WriteLine($"{i} {mincost[i]}");
        }
    }
