		int ans = Integer.MAX_VALUE;

		if (L / 2019 != 0 && R / 2019 != 0 && R / 2019 - L / 2019 >= 2) {
			ans = 0;
		}
		else if (L / 2019 == 0 && R / 2019 != 0 && R / 2019 - L / 2019 >= 2) {
			ans = 0;
		}
		else if (L / 2019 != 0 && R / 2019 == 0 && R / 2019 - L / 2019 >= 2) {
			ans = 0;
		}
		else if (L / 2019 == 0 && R / 2019 == 0 && R / 2019 - L / 2019 >= 1) {
			ans = 0;
		}
		else {
			for (int i = L; i < R; i++) {
				for (int k = i+1; k <= R; k++) {
					int keep = (i % 2019) * (k % 2019);
					keep %= 2019;
					if (keep < ans) {
						ans = keep;
					}
				}
			}
		}
