namespace ConsoleApp2
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine())+1;
            var memo = new List<int>(Enumerable.Range(0, N).Select(s => int.MaxValue));
            var t6 = new List<int>();
            var t9 = new List<int>();
            for (var i = 1; i < N; i++)
            {
                var tmp = (int)Math.Pow(6, i);
                if (N < tmp) break;
                t6.Add(tmp);
            }
            for (var i = 1; i < N; i++)
            {
                var tmp = (int)Math.Pow(9, i);
                if (N < tmp) break;
                t9.Add(tmp);
            }
            Action<List<int>, int, int> chmin =
                (ls, index, val) =>
                {
                    if (val < ls[index]) ls[index] = val;
                };
            memo[0] = 0;
            for (var i = 1; i < N; i++)
            {
                chmin(memo, i, memo[i-1]+1);
                for (var k = 0; k<t6.Count; k++)
                {
                    if (i - t6[k] < 0) continue;
                    chmin(memo, i, memo[i - t6[k]] + 1);
                }
                for (var k = 0; k < t9.Count; k++)
                {
                    if (i - t9[k] < 0) continue;
                    chmin(memo, i, memo[i - t9[k]] + 1);
                }
            }
            Console.WriteLine(memo[N - 1]);
        }
    }
}

