                CS[a] += a;
            }
            for (int i = MAX - 1; i >= 0; i--) {
                CS[i] += CS[i + 1];
            }

            int min = 0;
            int max = MAX * 2 + 1;

            while (Math.abs(min - max) > 1) {
                int mid = (min + max) / 2;

                long K = 0;
                for (int a : A) {
                    if (mid - a > MAX) {
                        continue;
                    }

                    K += C[Math.max(mid - a, 0)];
                }

                if (K < M) {
                    max = mid;
                } else {
                    min = mid;
                }
            }

            long H = 0;
            long K = 0;
            for (int a : A) {
                if (max - a > MAX) {
                    continue;
                }

                H += a * C[Math.max(max - a, 0)] + CS[Math.max(max - a, 0)];
                K += C[Math.max(max - a, 0)];
            }

            H += min * (M - K);

            System.out.println(H);
        }
    }

}

