            A[i] = long.Parse (strtemp[0]);
            B[i] = long.Parse (strtemp[1]);
        }

        quickSortB2S (A);
        quickSortB2S (B);

        if (N % 2 == 0) {
            Console.WriteLine (B[N / 2] + B[N / 2 - 1] - A[N / 2] - A[N / 2 - 1] + 1);
        } else {
            Console.WriteLine (B[(N - 1) / 2] - A[(N - 1) / 2] + 1);
        }
    }

    static void quickSortB2S (long[] a) {
        quickSortB2S (a, 0, a.Length - 1);
    }

    static void quickSortB2S (long[] a, int left, int right) {
        if (left < right) {
            int i = left;
            int j = right;
            long tmp;
            long pivot = med3 (a[i], a[i + (j - i) / 2], a[j]);
            while (true) {
                while (a[i] > pivot) i++;
                while (pivot > a[j]) j--;
                if (i >= j) break;
                tmp = a[i];
                a[i] = a[j];
                a[j] = tmp;
                i++;
                j--;
            }
            quickSortB2S (a, left, i - 1);
            quickSortB2S (a, j + 1, right);
        }
    }

    static long med3 (long x, long y, long z) {
        if (x < y) {
            if (y < z) {
                return y;
            } else if (z < x) {
                return x;
            } else {
                return z;
            }
        } else {
            if (z < y) {
                return y;
            } else if (x < z) {
                return x;
            } else {
                return z;
            }
        }

    }

    //1000000007
}

