		int free = Math.min(n, k); //max zeroes
		int rest = n - free;
		q = (ainb(n,n))%MOD;
//		System.out.println("starts with " + q);

		for(int i = free+1; i < n; i++)
		{
//			System.out.println("Can't have " + i + " zeroes");
			int nonzero = n-i;
