		long B = B2;
		for(var i=r1;i<=r2;i++){
			A = A * (i+c2+1) % mod * Mpow(i+1,mod-2,mod) % mod;
			B = (B + A) % mod;
		}
		Console.WriteLine((B-B2-B3+B4+mod+mod)%mod);
	}
	public static long Mpow(long x,long n,long m)
	{
		long ans = 1;
		while(n > 0){
			if(n % 2 == 1){
				ans = ans * x % m;
				n -= 1;
			}
			x = x * x % m;
			n /= 2;
		}
		return ans;
	}
}

