			if(!dic.ContainsKey(A[i])){
				dic[A[i]] = i;
			}
		}
		long[]S = new long[N];
		long sum = 0;
		for(var i=N-1;i>=0;i--){
			sum += A[i];
			S[i] = sum;
		}
		int min = P;
		int max = N;
		while(min<max){
			int m = (min+max)/2;
          	//Console.Error.WriteLine(min+" "+max+" "+m+" "+A[m]);
			long a = A[m]+M;
			int min2 = 0;
			int max2 = m;
