            {
                for (var i = 0; i < n; ++i)
                {
                    if ((s[i] - '0') % p == 0)
                    {
                        total += i + 1;
                    }
                }
            }
            else
            {
                var digit = 1;
                var current = 0L;
                var mods = new int[p];
                for (var i = n - 1; i >= 0; --i)
                {
                    current = (current + (s[i] - '0') * digit) % p;
                    total += mods[current] + (current == 0 ? 1 : 0);
                    ++mods[current];
                    digit = digit * 10 % p;
                }
            }
            WriteLine(total);
        }
    }
