         long[] invfac = new long[500001];
         fac[0] = invfac[0] = 1L;
         for(int i=1; i <= 500000; i++)
         {
            fac[i] = (fac[i-1]*i)%MOD;
            invfac[i] = power(fac[i], MOD-2, MOD);
         }
         long other = 0L;
         for(int c=0; c <= N; c++) 
         {
            long temp = (fac[N]*invfac[c])%MOD;
            temp = (temp*invfac[N-c])%MOD;
            //temp = (temp*fac[M-c])%MOD;
            int leftover = N-c;
            int choices = M-c;

            long boof = (fac[choices]*invfac[choices-leftover])%MOD;
            //boof = (boof*invfac[choices-leftover])%MOD;
            temp = (temp*boof)%MOD;

            if(c%2 == 1)
               temp *= -1;
            other += temp+MOD;
            other %= MOD;
         }
         res = (res*other)%MOD;
         System.out.println(res);
      }
      public static long power(long x, long y, long p) 
      { 
          long res = 1L;      
          x = x % p;  
          while (y > 0) 
          { 
              if((y & 1)==1) 
                  res = (res * x) % p; 
              y = y >> 1;  
              x = (x * x) % p;  
          } 
          return res; 
      }
   }

