using System.Linq;

namespace contest_Csharp
{
    class Program
    {
        static void Main(string[] args)
        {

            var vals = Console.ReadLine().Split(' ')
                .Select(x => int.Parse(x)).ToList();
            var N = vals[0];
            //var K = vals[1];


            var A = Console.ReadLine().Split(' ')
                .Select(x => int.Parse(x)).ToList();
            List<(long, int)> ps = new List<(long, int)>();
            for (int i = 0; i < N; i++)
            {
                ps.Add((A[i], i));
            }
            ps.Sort();
            ps.Reverse();
            List<List<long>> dp=new List<List<long>>();
            dp.Add (new List<long>());
            dp[0].Add(0);
            for (int i = 1; i <= N; i++)
            {
                dp.Add(new List<long>(new long[i + 1]));
                dp[i][0] = dp[i - 1][0] + ps[i-1].Item1 * Math.Abs((N - 1) - (i-1) - ps[i-1].Item2);
                for (int k = 1; k < i; k++)
                {
                    dp[i][k] = Math.Max(dp[i - 1][k - 1] + ps[i-1].Item1 * Math.Abs(ps[i-1].Item2 - (k - 1)),
                       dp[i - 1][k] + ps[i-1].Item1 * Math.Abs((N-1)-(i-1-k)-ps[i-1].Item2));
                }
                dp[i][i] = dp[i - 1][i - 1] + ps[i-1].Item1 * Math.Abs(ps[i-1].Item2 - (i - 1));
            }
            long ans = 0;
            for (int i = 0; i <= N; i++)
            {
                ans = Math.Max(ans, dp[N][i]);
            }
            Console.WriteLine(ans);


        }



    }
}

