            int m = (l + r) /2;
            int tmp = m;
            boolean over = false;
            boolean odd = false;
            for (int i = 0; i < n; i++) {
                if(a[i] < tmp){
                    if(i % 2 != 0) odd = true;
                    over = true;
                    break;
