                tmp = a[i] - tmp;
            }
            if((over&&odd) || (!over && m <= tmp)) l = m;
            else r = m;
        }
        int[] ans = new int[n];
        ans[0] = l;
        StringBuilder sb = new StringBuilder();
        sb.append(ans[0] * 2).append(" ");
        for (int i = 1; i < n; i++) {
