        int baseAll = 0;
        int[] base2 = new int[19];
        int[] base5 = new int[19];
        for (int i=0;i<n;i++){
            if (data[i][0]>=18&&data[i][1]>=18)baseAll++;
            else if (data[i][0]>=18){
                for (int j=18-data[i][1];j<19;j++)base2[j]++;
            }
            else if (data[i][1]>=18){
                for (int j=18-data[i][0];j<19;j++)base5[j]++;
            }
