                var sqrt = Sqrt(target);
                long divisorNum = 1;
                var canDivide = false;
                for(var j = 0; j < primes.Count; j++)
                {
                    var prime = primes[j];
                    if(prime > sqrt)
                    {
                        break;
                    }
                    if(!isPrime[prime])
                    {
                        continue;
                    }
                    var count = 0;
                    while(target % prime == 0 && target != 1)
                    {
                        target /= prime;
                        count++;
                        canDivide = true;
                    }
                    divisorNum *= count + 1;
                    if(canDivide)
                    {
                        divisorNum *= divisorNums[target];
                        break;
                    }
                }
                if (target != 1 && !canDivide)
                {
                    divisorNum *= 2;
                }
                divisorNums[i] = divisorNum;
            }

            long sum = 0;
            for(var i = 1; i <= n; i++)
            {
                sum += i * divisorNums[i];
            }

            WriteLine(sum);
        }
    }
}

