            for (; i <= 20; i++)
            {
                if ((L & 1) == 1) stack.Push(i);
                L >>= 1;
                if (L == 0) break;
                path.Add(i + " " + (i + 1) + " " + 0);
                path.Add(i + " " + (i + 1) + " " + sum);
                sum <<= 1;
            }
            stack.Pop();
            while (stack.Count > 0)
            {
                var idx = stack.Pop();
                path.Add(idx + " " + i + " " + sum);
                sum += Enumerable.Repeat(2, idx - 1).Aggregate(1, (x, y) => x * y);
