		String T = sc.next();
		sc.close();

		if(N < M) {
			int cap = N;
			N = M;
			M = cap;
			String cap2 = S;
			S = T;
			T = cap2;
		}

		if(S.equals(T)) {
			System.out.println(N);
		} else if(S.charAt(0) != T.charAt(0)){
			System.out.println("-1");
		} else if(M == 1) {
			System.out.println(N);
		} else if(N % M == 0){
			boolean flag = true;
			for(int i = 0;i < M;++i) {
				if(S.charAt(i*(N/M)) != T.charAt(i)) {
					flag = false;
					break;
				}
			}
			if(flag) {
				System.out.println(N);
			} else {
				System.out.println("-1");
			}
		} else {
			boolean flag = true;
			int gcd = 0;
			int n = N;
			int m = M;
			while(true) {
				if(n < m) {
					int cap = n;
					n = m;
					m = cap;
				}
				if(n == m) {
					gcd = n;
					break;
				}else if(n % m == 0){
					gcd = m;
					break;
				}else {
					n -= (n/m) * m;
				}
			}
			long ans = (((long)N*(long)M)/(long)gcd);

			int swidth = (int)(ans/N);
			int twidth = (int)(ans/M);
			for(int sidx = 0, tidx = 0;sidx < N || tidx < M;) {
				if(sidx * swidth == tidx * twidth) {
					if(S.charAt(sidx) != T.charAt(tidx)) {
						flag = false;
						break;
					}
					sidx++;
					tidx++;
					continue;
				}
				if(sidx * swidth > tidx * twidth) {
					int cap = (sidx * swidth - tidx * twidth) / twidth;
					if(cap > 0)
						tidx += cap;
					else
						tidx++;
				}else {
					int cap = (tidx * twidth - sidx * swidth) / swidth;;
					if(cap > 0)
						sidx += cap;
					else
						sidx++;
				}
			}
			if(flag) {
				System.out.println(ans);
			}else {
				System.out.println("-1");
			}
		}
	}
