        var array2 = Console.ReadLine().Split(' ');

        var aBooks = new List<long>();
        var bBooks = new List<long>();

        long current = 0;
        long ans = 0;

        foreach (var book in array1)
        {
            var time = long.Parse(book);
            if(current + time <= K)
            {
                aBooks.Add(time);
                current += time;
            }
            else
            {
                break;
            }
        }

        ans = aBooks.Count;
        var currentCount = ans;

        foreach(var book in array2)
        {
            bBooks.Add(long.Parse(book));
        }

        int currentBPlace = 0;


        while (true)
        {
            if (currentBPlace >= bBooks.Count)
            {
                break;
            }
            if (bBooks[currentBPlace] + current <= K)
            {
                current += bBooks[currentBPlace];
                currentBPlace += 1;
                currentCount += 1;

                if (currentCount > ans)
                {
                    ans = currentCount;
                }
            }
            else
            {
                break;
            }
        }



        for (int i = aBooks.Count - 1; i >= 0; i--)
        {
            if(currentBPlace >= bBooks.Count)
            {
                break;
            }

            currentCount -= 1;
            current -= aBooks[i];

            while (true)
            {
                if (currentBPlace >= bBooks.Count)
