    public static void Main()
    {
        int N = int.Parse(Console.ReadLine());
        List<Tuple<int, int>> K = new List<Tuple<int, int>>() { Capacity = N};
        for(int i = 0; i < N; i++)
        {
            var s = Console.ReadLine().Split(' ');
            int A = int.Parse(s[0]);
            int B = int.Parse(s[1]);
            K.Add(new Tuple<int, int>(B, A));
        }

        K.Sort((x, y) =>
        {
            if (x.Item1 < y.Item1)
                return 1;
            else if (x.Item1 > y.Item1)
                return -1;
            else
            {
                if (x.Item2 < y.Item2)
                    return 1;
                else if (x.Item2 > y.Item2)
                    return -1;
                else
                    return 0;
            }
        });

        int j, CT = K[0].Item1;
        for(j = 0; j < N; j++)
        {
            CT = Math.Min(CT, K[j].Item1) - K[j].Item2;
        }
        if (j == N && CT >= 0)
            Console.WriteLine("Yes");
        else
            Console.WriteLine("No");
    }
}

