using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

class Program
{
    static void Main(string[] args)
    {
        long ansCount = 0;
        var s = Console.ReadLine().Select(c => c - '0').Reverse().ToArray();
        int n = s.Length;
        long[] ten = new long[n];
        ten[0] = 1;
        for(int i = 0; i < n - 1; i++)
        {
            ten[i + 1] = (ten[i] * 10) % 2019;
        }
        long[] ans = new long[n];
        ans[0] = s[0];
        if (ans[0] == 0) ansCount++;
        for(int i = 0; i < n -1; i++)
        {
            ans[i + 1] = (ans[i] + (s[i+1] * ten[i+1]) )% 2019;
            if (ans[i + 1] == 0) ansCount++;
        }
        var a = ans.GroupBy(x => x);
        foreach(var ele in a)
        {
            if(ele.Count() > 1)
            {
                ansCount += (ele.Count() * (ele.Count() - 1)) / 2;
            }
        }
        Console.WriteLine(ansCount);

    }


}

