        {

            if (C > D)
            {
                C = C % D;
            }
            else if (D > C)
            {
                D = D % C;
            }

            if (C == 1|D==1)
            {

                break;
            }
            else if (C == 0 | D == 0)
            {
                break;
            }
        }
        double ans;
        if (C == 0)
        {
            ans = (A * B) / D;
        }
        else if (D == 0)
        {
            ans = (A * B) / C;
        }
        else
            ans = A * B;

        Console.WriteLine(ans);
    }
