using System.Text;
using System.Threading.Tasks;

namespace ConsoleApp62 {
    class Program {
        static void Main(string[] args) {
            int N = int.Parse(Console.ReadLine());

            int type_A = 0;

            //〇×〇×〇×△型を探す
            for (int k = 1; k <= N; k += 2) {
                for (int i = 1; i * i * i <= k; i++) {
                    if (!isPrime(i)) {
                        continue;
                    }
                    if (k % i == 0 && k % (i * i) == 0 && k % (i * i * i) == 0 && k / (i * i * i) != i) {
                        if (isPrime(k / (i * i * i))) {
                            //Console.WriteLine("(k, i) = " + k + " " + i);
                            type_A++;
                        }
                    }
                }
            }

            int type_B = 0;

            //〇×△×◇型を探す
            for (int i = 1; i * (i + 1) * (i + 2) <= N; i += 2) {
                for (int j = i + 2; i * i * j <= N; j += 2) {
                    for (int k = j + 2; i * j * k <= N; k += 2) {
                        if (isPrime(i) && isPrime(j) && isPrime(k) && i * j * k <= N) {
                            //Console.WriteLine("(i, j, k) = " + i + " " + j + " " + k);
                            type_B++;
                        }
                    }
                }
            }


            Console.WriteLine(type_A + type_B);
        }

        //素数かどうかを返す
        static bool isPrime(int N) {
            if (N == 1) {
                return false;
            }

            if (N == 2 || N == 3) {
                return true;
            }

            for (int i = 2; i * i <= N; i++) {
                if (N % i == 0) {
                    return false;
                }
            }

            return true;
        }
    }
}

