        {
            Console.WriteLine("1");
            return;
        }

        if (a.Distinct().Count() == 1)
        {
            Console.WriteLine("0");
            return;
        }

        long ans = 0;

        n = a.Length;
        long max = a.Max();
        bool[] isNG = new bool[max + 1];


        a = a.OrderBy(t => t).ToArray();

        for (long i = 0; i < n; i++)
        {
            if (i == 0)
            {
                for (long tmp = 1; tmp < 1000000; tmp++)
                {
                    if (a[i] * tmp > max) break;
                    isNG[a[i] * tmp] = true;
                }

                if (i < n - 1)
                {
                    if (a[i] == a[i + 1]) continue;
                }

                ans++;

                continue;
            }

            bool flag = false;
            if (isNG[a[i]]) flag = true;
            for (long tmp = 1; tmp < 1000000; tmp++)
            {
                if (a[i] * tmp > max) break;
                isNG[a[i] * tmp] = true;
