    {

        const int INF = 1000000009;

        static int Prim(int V, int[,] g)
        {
            int[] d = new int[V];
            for (int i = 0; i < V; i++) d[i] = INF;
            d[0] = 0;
            bool[] visit = new bool[V];

            while (true)
            {
                int from = -1;
                int mincost = INF;

                for(int i = 0; i < V; i++)
                {
                    if(!visit[i])
                    {
