	{
		static void Main(string[] args)
		{
			var n = long.Parse(ReadLine());
			var sqrtN = Sqrt(n);
			var factors = new Dictionary<long, long>();

			if (n == 1)
			{
				WriteLine(0);
				return;
			}

			for (long i = 2; i <= sqrtN + 2; i += 2)
			{
				while (n % i == 0)
				{
					if (!factors.ContainsKey(i))
					{
						factors.Add(i, 0);
					}
					factors[i]++;
					n /= i;

					if (n == 1)
					{
						break;
					}
				}
				if (n == 1)
				{
					break;
				}
				if (i == 2)
				{
					i--;
				}
			}

			if(n != 1)
			{
				factors.Add(n, 1);
			}

			if (!factors.Any())
			{
				WriteLine(1);
				return;
			}

			long count = 0;
			foreach (var value in factors.Values)
			{
				var tmp = value;
				long i = 1;
				while (tmp > 0)
				{
					if (tmp - i > i || tmp - i == 0)
					{
						tmp -= i;
						count++;
					}
					i++;
				}
			}

			WriteLine(count);
		}
	}
