		string[] args;

		args = Console.ReadLine().Split(' ');
		long d = Int64.Parse(args[0]);
		long g = Int64.Parse(args[1]);

		long[] p = new long[d+1];
		long[] c = new long[d+1];

		for( int i = 1; i <= d; i++ ){
			args = Console.ReadLine().Split(' ');
			p[i] = Int64.Parse(args[0]);
			c[i] = Int64.Parse(args[1]);			
		}

		long[] total = new long[d+1];
		for( int i = 1; i <= d; i++ ){
			total[i] = 100 * i * p[i] + c[i];
		}

		long minNumSolve = Int64.MaxValue; 
		for( int s = 0; s < (1 << (int)d); s++ ){

			long point = 0;
			long numSolve = 0;

			for( int i = 0; i < d; i++ ){
				if( ((s >> i) & 1) == 0 ) continue;
				point += total[i+1];
				numSolve += p[i+1];
			}

			if( point >= g ){
				if( numSolve < minNumSolve ) minNumSolve = numSolve;
				continue;			
			}

			for( int i = 0; i < d; i++ ){
				long rest = g - point;
				if( ((s >> i) & 1) == 1 ) continue;
				if( rest > 100 * (i + 1) * p[i+1] ) continue;
				long tmpNumSolve = numSolve;
				tmpNumSolve += rest / ( 100 * (i + 1) );
				if( rest % (100 * (i + 1)) != 0 ) tmpNumSolve++;
				if( tmpNumSolve < minNumSolve ) minNumSolve = tmpNumSolve;
			}		

		}

		Console.WriteLine(minNumSolve);		

	}

}

