	for (int i = 0; i < N; i++)
	{
	    d0[i] = new List<int>();
	}

	for (int i = 0; i < s.Length; i++)
	{
	    char c = s[i];
	    d0[c-'a'].Add(i);
	}

	int [][] d = new int[N][];
	for (int i = 0; i < N; i++)
	{
	    d[i] = d0[i].ToArray();
	}

	int [,] m = new int[s.Length, N];

	for(int i = 0; i < s.Length; i++)
	{
	    for (int j = 0; j < N; j++)
	    {
		if (d[j].Length > 0)
		{
		    int x = Array.BinarySearch(d[j], i);
		    if (x < 0)
		    {
			x = ~x;
			if (x >= d[j].Length){ x = 0; }
		    }
		    int pos = d[j][x];
		    if (pos >= i){ pos -= i; }
		    else         { pos += s.Length - i; }
		    m[i, j] = pos + 1;
		}
	    }
	}

	long ans = 0;
