      {
        if(s[i] == '0') minNum = i;
        leftNum--;
      }
      //Console.WriteLine(minNum);

      if(minNum == minNumBefore)
      {
        answer = false;
        break;
      }else
      {
        answers.Add(minNumBefore -minNum);
        minNumBefore = minNum;
        if(minNum == 0) break;
