    {
        const long INF = (long)1 << 32;
        static void Main(string[] args)
        {
            var a = scan;
            int n = a[0];
            int e = a[1];
            var d = new long[n, n];
            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < n; j++)
                {
                    d[i, j] = i == j ? 0 : INF; 
                }
            }
            for (int i = 0; i < e; i++)
            {
                var f = scan;
                d[f[0], f[1]] = f[2];
            }

            for (int k = 0; k < n; k++)
            {
                for (int i = 0; i < n; i++)
                {
                    if (d[i, k] == INF) continue;
                    for (int j = 0; j < n; j++)
                    {
                        if (d[k, j] == INF) continue;
                        d[i, j] = Math.Min(d[i, j], d[i, k] + d[k, j]);
                    }
                }
            }

            bool posi = true;
            for (int i = 0; i < n; i++)
            {
                if (d[i,i]<0)
                {
                    posi = false;
                    Console.WriteLine("NEGATIVE CYCLE");
                    break;
                }
            }

            if (posi)
            {
                var ans = new StringBuilder();
                for (int i = 0; i < n; i++)
                {
                    string st= "";
                    for (int j = 0; j < n; j++)
                    {
                        if (d[i, j] == INF) st += "INF ";
                        else st += d[i, j] + " ";
                    }
                    ans.AppendLine(st.Trim());
                }
