            }
            Array.Sort(A);
            var b = new int[2];
            var flg = false;
            if (N % 2 == 0)
            {
                b[0] = A[N / 2 - 1];
                b[1] = A[N / 2];
                flg = true;
            }
            else
            {
                b[0] = A[N / 2];
            }
            var sum = 0L;
