using System.Runtime.InteropServices;
using System.Runtime.Intrinsics.X86;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;

namespace AtCoder
{
	public class Program
	{
		static void Main()
		{
			var nm = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
			int n = nm[0];
			int m = nm[1];

			var ab = new (int a, int b)[m];
			for (int i = 0; i < m; i++) {
				var abtemp = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
				ab[i] = (abtemp[0] - 1, abtemp[1] - 1);
			}

			var parents = new int[n];
			var counts = new int[n];
			for (int i = 0; i < n; i++) {
				parents[i] = i;
				counts[i] = 1;
			}

			int Find(int v)
			{
				while (v != parents[v]) {
					v = parents[v];
				}

				return v;
			}

			void Union(int x, int y)
			{
				int px = Find(x);
				int py = Find(y);
				if (px == py) {
					return;
				}

				if (counts[px] < counts[py]) {
					parents[px] = py;
					counts[py] += counts[px];
				} else {
					parents[py] = px;
					counts[px] += counts[py];
				}
			}

			long Count(int v)
			{
				return counts[Find(v)];
			}

			var ans = new long[m];
			var temp = (long)n * (n - 1) / 2;
			ans[m - 1] = temp;
			for (int i = m - 1; i > 0; i--) {
				int a = ab[i].a;
				int b = ab[i].b;
				if (Find(a) != Find(b)) {
					temp -= Count(a) * Count(b);
					Union(a, b);
				}

				ans[i - 1] = temp;
			}

			Console.WriteLine(string.Join(Environment.NewLine, ans));
		}
	}
}

