                .Select(x => int.Parse(x)).ToList();
            N = prop[0];
            K = prop[1];
            C = prop[2];
            string S = Console.ReadLine();
            List<long> frontwork = new List<long>(), backwork = new List<long>(),
                recastleft = new List<long>(), capacity = new List<long>();
            long f = 0;
            long recast = 0;
            for (int i = 0; i < N; i++)
            {
                frontwork.Add(f);
                recastleft.Add(recast);


                if (S[i] == 'o' && recast == 0)
                {
                    f++;
                    recast = C;
                }
                else
                {
                    recast = Math.Max(recast - 1, 0);

                }
            }
            long b = 0;
            long brecast = 0;
            for (int i = (int)N - 1; i >= 0; i--)
            {
                backwork.Add(b);
                capacity.Add(C - brecast);


                if (S[i] == 'o' && brecast == 0)
                {
                    b++;
                    brecast = C;
                }
                else
                {
                    brecast = Math.Max(brecast - 1, 0);
                }
            }
            backwork.Reverse();
            capacity.Reverse();
            for (int i = 0; i < N; i++)
            {
                if (S[i] == 'o')
                {
                    if (frontwork[i] + backwork[i] < K ||
                        (frontwork[i] + backwork[i] == K && capacity[i] - recastleft[i] > C))
                    {
                        Console.Write((i + 1) + " ");
                    }
                }
