            {
                totalCnt++;
                continue;
            }
            double max = Math.Sqrt(AB);
            int cnt = 0;
            for (int j = 1; j < max; j++)
            {
                if(AB % j == 0)
                {
                    cnt++;
                }
            }

            totalCnt += cnt * 2;

