    class Program
    {
        static void Main(string[] args)
        {
            var NM = (Console.ReadLine().Split().Select(x => int.Parse(x))).ToList();
            var N = NM[0];
            var M = NM[1];

            var X = (Console.ReadLine().Split().Select(x => int.Parse(x))).ToList();
            X.Sort();
            var xs = new List<int>();
            var rmd = new Dictionary<int, List<int>>();

            // 差のリスト
            for (int i = 0; i < X.Count - 1; i++)
            {
                var sub = Math.Abs(X[i] - X[i + 1]);
                xs.Add(sub);
                if (!rmd.ContainsKey(sub)) rmd.Add(sub, new List<int>());
                rmd[sub].Add(i);
            }

            if (M == 1 || N >= M)
                // 地点1個または石が地点以上にある
                Console.WriteLine(0);
            else if (N == 1)
                // 石1個
                Console.WriteLine(Math.Abs(X.Last() - X.First()));
            else
            {
                var xsm = xs.OrderBy(x => x).ToList();
                var bun = new List<int>();

                // 差が大きいところで分割
                for (int i = 0; i < N - 1; i++)
                {
                    var im = xsm[xsm.Count() - i - 1];
                    var im_idxs = rmd[im];
                    bun.Add(im_idxs[0]);
                    im_idxs.RemoveAt(0);
                }

                bun.Sort();

                int re = 0;
                // 区間毎に移動量を算出
                for (int i = 0; i < N; i++)
                {
                    int l = 0;
                    int r = 0;

                    if (i == 0)
                    {
                        l = 0;
                        r = bun[0];
                    }
                    else if (i == N - 1)
                    {
                        l = bun[i - 1] + 1;
                        r = X.Count() - 1;
                    }
                    else
                    {
                        l = bun[i - 1] + 1;
                        r = bun[i];
                    }

                    re += Math.Abs(X[l] - X[r]);
                }

                Console.WriteLine(re);

            }

        }

    }
}

