                }
                continue;
            }

            int t = circle[i];
            if (t >= 3) {
                System.out.println(0);
                return;
            } else if (t == 2) {
                circle[i] = 1;
                circle[24 - i] = 1;
            } else if (t == 1) {
                circle[i] = -1;
            }
