            Int64 a = 1000000000000;
            Int64 j = 0;

            for (Int64 i = 2; i <= Math.Sqrt(N); i++)
            {
                if (N % i == 0)
                {
                    j = N / i;
                    if (a > (i - 1) + (j - 1))
                    {
                        a = (i - 1) + (j - 1);
                    }
                }
            }
            if (a == 1000000000000)
            {
                a = N - 1;
            }
            Console.WriteLine(a);
        }
    }
