                long wnum = 0;
                for(int j=i+1; j<n; j++){
                    if(!stone[j]) wnum++;
                }
                for(int j=i+1; j<n; j++){
                    if(!stone[j]) ans += j-i;
                }
                if(wnum > 0) ans -= (wnum-1) * (wnum) / 2; 
                break;
            }
        }

        System.out.println(ans);
    }
