            double[] INPUT = Console.ReadLine().Split().Select(double.Parse).ToArray();
            double[,] H = new double[N, 2];

            for (int i = 0; i < N; i++)
            {
                H[i, 0] = INPUT[i];
                H[i, 1] = 1;
            }

            int p = 1;
            Boolean check = true;

            if (N == 2)
            {
                if (H[0, 0] - 1 > H[1, 0])
                {
                    check = false;
                }
            }

            while (p <= N - 2)
            {

                if (H[p - 1, 0] <= H[p, 0] && H[p, 0] <= H[p + 1, 0])
                {
                    p++;
                }
                else if (H[p - 1, 1] == 1 && H[p - 1, 0] > H[p, 0])
                {
                    H[p - 1, 0] -= 1;
                    H[p - 1, 1] = 0;
                    p = (p > 3 ? p - 2 : 1);
                }
                else if (H[p, 1] == 1 && H[p + 1, 0] < H[p, 0])
                {
                    H[p, 0] -= 1;
                    H[p, 1] = 0;
                    p = (p > 3 ? p - 2 : 1);
                }
                else
                {
                    check = false;
                    break;
                }
            }

            Console.WriteLine(check ? "Yes" : "No");
        }
    }
