        string strInput = Console.ReadLine();
        char[] cInput = strInput.ToCharArray();
        int result = 0;

        int startRNum = 0;  //Rで始まる。
        int endWNum = 0;

        i = 0;
        while (cInput[i] == 'R')
        {
            startRNum++;
            i++;
            if (i >= n) break;
        }

        i = n - 1;
        while(cInput[i] == 'W')
        {
            endWNum++;
            i--;
            if (i < 0) break;
        }

        //R...RW...Wになっている。またはどっちかの色のみ
        if ( startRNum + endWNum == n)
        {
            Console.WriteLine(0);
            return;
        }

        int lPtr = 0;
        int rPtr = n - 1;
        while (true)
        {
            while (cInput[lPtr] == 'R' && lPtr < n) lPtr++;
            while (cInput[rPtr] == 'W' && rPtr >= 0) rPtr--;

            if(lPtr >= rPtr)
            {
                break;
            }

            cInput[lPtr] = 'R';
            cInput[rPtr] = 'W';
            result++;

        }

        Console.WriteLine(result);

        return;
