    static void Main()
    {
        var nk = Console.ReadLine().Split(' ').Select(x => Int32.Parse(x)).ToArray();
        var N = nk[0];
        var K = nk[1];
        var S = Console.ReadLine();
        var list = new List<int[]>();
        var currentNum = -1;
        var currentNumCount = 0;
        var zeroCount = 0;
        var isFirstZero = false;
        var allCount = 0;
        for (int i=0;i<N;++i)
        {
            if (currentNum != S[i])
            {
                allCount++;
                if (currentNum == -1) isFirstZero = S[i] == '0';
                if (S[i] == '0') zeroCount++;
                if (currentNum != -1) list.Add(new int[2]{currentNum,currentNumCount});
                currentNum = S[i];
                currentNumCount = 1;
            }
            else currentNumCount++;
            if (i == N - 1) list.Add(new int[2] { currentNum, currentNumCount });
        }
        var ans = 0;
        var count = zeroCount - K+1;
        //isFirstZero 0246 else 1357
        //一番初め
        var c = 0;
        if (isFirstZero)
        {
            var iC = 2 * K-1;
            for (int i=0;i<=iC;++i) if (i < allCount) c += list[i][1];
        }
        else
        {
            var iC = 2 * K;
            for (int i = 0; i <= iC; ++i) if (i < allCount) c += list[i][1];
        }
        if (ans < c) ans = c;
        //累積和
        for (int i=1;i<count;++i)
        {
            //引く
            if (i == 1 && isFirstZero)
            {
                c -= list[0][1];
            }//0246
            else if(isFirstZero)
            {
                c -= (list[(i - 1) * 2][1] + list[(i - 1) * 2-1][1]);
            }//1357
            else
            {
                c -= (list[(i - 1) * 2][1] + list[(i - 1) * 2+1][1]);
            }
            //足す
            //0246
            if (isFirstZero)
            {
                var addIndex = (i + K - 1) * 2;
                c += list[addIndex][1];
                if(addIndex+1<allCount)c+= list[addIndex + 1][1];
            }//1357
            else
            {
                var addIndex = (i + K - 1) * 2 + 1;
                c += list[addIndex][1];
                if(addIndex+1<allCount) c += list[addIndex+1][1];
            }
            if (ans < c) ans = c;
        }
        Console.WriteLine(ans);
    }
