    class EDPC_G
    {
        public static void Main()
        {
            var nm = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
            var n = nm[0];
            var m = nm[1];

            var nodes = new List<int>[n];
            var inN = new int[n];

            for (int i = 0; i < m; i++)
            {
                var xy = Console.ReadLine().Split(' ').Select(s => int.Parse(s) - 1).ToArray();
                if (nodes[xy[0]] == null)
                    nodes[xy[0]] = new List<int>();
                if (nodes[xy[1]] == null)
                    nodes[xy[1]] = new List<int>();
                nodes[xy[0]].Add(xy[1]);
                inN[xy[1]]++;
            }

            var queue = new Queue<int>();
            for (int i = 0; i < n; i++)
                if (nodes[i] != null && inN[i] == 0)
                    queue.Enqueue(i);

            int startN = queue.Count;

            var sorted = new List<int>();
            while (queue.Any())
            {
                var i = queue.Dequeue();
                sorted.Add(i);

                foreach (var j in nodes[i])
                {
                    inN[j]--;
                    if (inN[j] == 0)
                        queue.Enqueue(j);
                }
            }

            var longestParitial = new int[n];
            for (int i = sorted.Count - 1; i >= 0; i--)
            {
                if (!nodes[sorted[i]].Any())
                    continue;
                longestParitial[sorted[i]] = nodes[sorted[i]].Max(j => longestParitial[j]) + 1;
            }

            var longest = 1;
            for (int i = 0; i < startN; i++)
                if (longest < longestParitial[sorted[i]])
                    longest = longestParitial[sorted[i]];

            Console.WriteLine(longest);
        }
    }
}

