    class Scanner
    {
        public int[] Nums(int count) => Enumerable.Range(0, count).Select(_ => Num).ToArray();
        public int Num => int.Parse(Str);
        public long NumLong => long.Parse(Str);
        public double NumDouble => (double)NumLong;

        StringBuilder sb = new StringBuilder();

        public string Str => GetStr();
        public string GetStr()
        {
            sb.Clear();

            int r = 0;
            bool? b = null;
            do
            {
                r = Console.Read();
                b = IsBreak(r);
            } while (b == true);

            if (b == null)
                throw new Exception("input error: unexpected end of stream");

            do
            {
                sb.Append((char)r);
                r = Console.Read();
                b = IsBreak(r);
            } while (b == false);

            return sb.ToString();
        }

        bool? IsBreak(int c)
        {
            switch (c)
            {
                case -1:
                    return null;
                case (int)' ':
                case (int)'\n':
                case (int)'\r':
                    return true;
                default:
                    return false;
            }
        }
    }
}

