namespace ConsoleApp1
{
    class Program
    {
        static void Main(string[] args)
        {
            var list = new List<int>[201];
            var dic = new HashSet<int>[201];

            var K = int.Parse(Console.ReadLine());

            for (var k = 1; k <= K; k++)
            {
                list[k] = new List<int>();
                dic[k] = new HashSet<int>();

                for (var t = k; t >= 1; t--)
                {
                    if ((k % t) == 0)
                    {
                        list[k].Add(t);
                        dic[k].Add(t);
                    }
                }
            }

            var sum = 0L;

            for (var a = 1; a <= K; a++)
            {
                for (var b = 1; b <= K; b++)
                {
                    for (var c = 1; c <= K; c++)
                    {
                        var min = Math.Min(Math.Min(a, b), c);

                        foreach (var kouho in list[min])
                        {
                            if(dic[a].Contains(kouho) && dic[b].Contains(kouho) && dic[c].Contains(kouho))
                            {
                                sum += kouho;
                                goto fin;
                            }
                        }
                    fin:
                        continue;
                    }
                }
            }

            Console.WriteLine(sum);
        }
    }
}

