namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            string data = Console.ReadLine();

            int[] map = new int[data.Length + 1];
            map[0] = 0;
            int updown = 0;

            for (int i = 0; i < data.Length; i++)
            {
                if (data[i] == '\\') updown--;
                else if (data[i] == '/') updown++;

                map[i + 1] = updown;
            }

            List<int> areaList = new List<int>();
            int area = 0;

            bool isSearch = false;
            int searchNum;
            int nextPoint = 0;

            for (int i = 1; i < map.Length; i++)
            {
                if (!isSearch)
                {
                    if (map[i - 1] > map[i])
                    {
                        searchNum = i;

                        while (map[searchNum - 1] >= map[searchNum] && searchNum != map.Length - 1)
                        {
                            searchNum++;
                        }

                        int tempMax = map[searchNum];

                        while (map[i - 1] > map[searchNum] && searchNum != map.Length - 1)
                        {
                            searchNum++;
                            if (tempMax < map[searchNum]) tempMax = map[searchNum];
                        }

                        nextPoint = tempMax;
                        isSearch = true;
                    }
                }

                if (isSearch)
                {
                    if (map[i - 1] < map[i])
                    {
                        searchNum = i - 1;

                        while (map[i] != map[searchNum] && searchNum > 0)
                        {
                            searchNum--;
                        }

                        area += i - searchNum - 1;

                        if (map[i] == nextPoint)
                        {
                            areaList.Add(area);
                            area = 0;
                            isSearch = false;
                        }
                    }
                }
            }

            StringBuilder sb = new StringBuilder();
            sb.AppendLine(areaList.Sum().ToString());
            sb.Append(areaList.Count);
            foreach (var a in areaList) sb.Append(" " + a);
            Console.WriteLine(sb);
        }
    }
}

