using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace AtCoder {
    class XorBattle {
        static bool can(long X, List<long> A) {
            if (X == 0) {
                return true;
            }

            int oddPos = -1;
            for (int i = 0; i < A.Count; i++) {
                if (A[i] % 2 == 1) {
                    oddPos = i;
                    break;
                }
            }

            if (oddPos == -1) {
                if (X % 2 == 1) {
                    return false;
                }

                var B = new List<long>();
                foreach (var a in A) {
                    B.Add(a / 2);
                }

                return can(X / 2, B);
            } else {
                var B = new List<long>();
                for (int i = 0; i < A.Count; i++) {
                    if (i != oddPos) {
                        B.Add(A[i] % 2 == 0 ? A[i] : (A[i] ^ A[oddPos]));
                    }
                }

                return can(X % 2 == 0 ? X : (X ^ A[oddPos]), B);
            }
        }

        static void Main(string[] args) {
            var T = int.Parse(Console.ReadLine());
            for (int t = 0; t < T; t++) {
                int N = int.Parse(Console.ReadLine());
                long[] A = new long[N];
                var parts = Console.ReadLine().Split(' ');
                for (int i = 0; i < N; i++) {
                    A[i] = long.Parse(parts[i]);
                }
                string S = Console.ReadLine();

                var X = new List<long>();

                bool canWin = true;

                for (int i = N - 1; i >= 0; i--) {
                    if (S[i] == '0') {
                        if (!can(A[i], X)) {
                            X.Add(A[i]);
                        }
                    } else {
                        if (!can(A[i], X)) {
                            canWin = false;
                            break;
                        }
                    }
                }

                Console.WriteLine(canWin ? "0" : "1");
            }
        }
    }
}

