class Program
{
	static void Main(string[] args)
	{
		string[] str = Console.ReadLine().Split();
		int N = int.Parse(str[0]);
		int K = int.Parse(str[1]);
		string[] str2 = Console.ReadLine().Split();
		int[]A = new int[N];
		for(var i=0;i<N;i++){
			A[i] = int.Parse(str2[i]);
		}
		Array.Sort(A);
		long[]NC = new long[100010];
		long[]ND = new long[100010];
		NC[0] = 1;
		ND[0] = 1;
		NC[1] = 1;
		ND[1] = 1;
		long mod = 1000000007;
		for(var i=2;i<100010;i++){
			NC[i] = NC[i-1] * i % mod;
			ND[i] = ND[i-1] * Mpow(i,mod-2,mod) % mod;
			//Console.Error.WriteLine(NC[i]+" "+ND[i]);
		}
		long[]B = new long[100010];
		B[K-1] = 1;
		for(var i=K;i<100010;i++){
			long a1 = i;
			long b1 = i-K+1;
			B[i] = NC[a1] * ND[b1] % mod * ND[a1-b1] % mod;
			//Console.Error.WriteLine(B[i]+" "+a1+" "+NC[a1]+" "+(a1-b1)+" "+ND[a1-b1]);
		}
		long min1 = 0;
		long max1 = 0;
		for(var i=0;i<N;i++){
			min1 = min1 + B[i] * A[i] % mod;
		}
		for(var i=N-1;i>=0;i--){
			max1 = max1 + B[N-1-i] * A[i] % mod;
		}
		Console.Error.WriteLine(min1+" "+max1);
		Console.WriteLine((min1-max1+mod)%mod);
	}

	public static long Mpow(long x,long n,long m)
	{
		long ans = 1;
		while(n > 0){
			if(n % 2 == 1){
				ans = ans * x % m;
				n -= 1;
			}
			x = x * x % m;
			n /= 2;
		}
		return ans;
	}

	public static long Ncr(long n,long r,long m)
	{
		long ans = 1;
		for(var i=n-r+1;i<=n;i++){
			ans = ans * i % m;
		}
		for(var i=2;i<=r;i++){
			ans = ans * Mpow(i,m-2,m) % m;
		}
		return ans;
	}
}

